L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "大変だと思うけど、速やかに態勢を整えて一気に攻め立てよう。"
L9_1.m_Talk_ENG = "I know you're tired, but brace yourselves. We're pushing through."
