L9_1.m_Talk_THA = "ฉันรู้ว่าพวกเธอเหนื่อย แต่เตรียมตัวให้พร้อมนะ เราจะผ่านมันไปให้ได้"
L9_1.m_Talk_VTN = "Tôi biết bạn đang mệt mỏi, nhưng hãy chuẩn bị tinh thần. Chúng ta đang cố gắng vượt qua."
L9_1.m_Talk_SCN = "虽然会很辛苦，但大家赶紧整顿准备，争取一次性完成任务。"
L9_1.m_Talk_DEU = "Ich weiß, ihr seid müde – aber wappnet euch, wir ziehen es durch!"
L9_1.m_Talk_FRA = "Je sais que vous êtes fatiguées, mais accrochez-vous. On va y arriver."
