L13_1.m_Pos = "R"
L13_1.m_Talk_KOREA = "너희들이 이 좌표에 도달한 후로 시간이 얼마나 흘렀는지 알기나 해?"
L13_1.m_fTalkTime = 0.03
L13_1.m_Talk_JPN = "あなたたちがこの座標に着いてから、どれだけの時間が過ぎたかわかってる？"
L13_1.m_Talk_ENG = "Do you have any idea how much time has passed since you arrived here?"
L13_1.m_Talk_TWN = "妳知道從你們達到這個座標後，已經過了多少時間嗎？"
L13_1.m_Talk_THA = "รู้ไหมว่าเวลาผ่านไปแค่ไหนแล้วนับตั้งแต่ที่เธอมาถึงที่นี่?"
L13_1.m_Talk_VTN = "Bạn có biết đã bao lâu kể từ khi bạn đến đây không?"
L13_1.m_Talk_SCN = "你知道从你们到达这个坐标开始时间已经经过了多久吗？"
L13_1.m_Talk_DEU = "Hast du eine Ahnung, wie viel Zeit seit eurer Ankunft hier vergangen ist?"
L13_1.m_Talk_FRA = "Tu sais depuis combien de temps vous êtes arrivées ici ?"
L14_1 = {}
L14_1.m_CutScenKey_Talk = "EP5_ACT3_STAGE4_END@14#Talk"
L14_1.m_CutScenProcessKey = 14
L14_1.m_CutScenID = 185
