L14_1.m_Pos = "R"
L14_1.m_Talk_KOREA = "아무리 정보 전달망을 교란하고 있다고 해도 한계가 있어."
L14_1.m_fTalkTime = 0.03
L14_1.m_Talk_JPN = "敵の情報伝達網を撹乱させているとはいえ、限界はあるのよ。"
L14_1.m_Talk_ENG = "We can only do so much by disturbing their lines of communication."
L14_1.m_Talk_TWN = "就算我們有在干擾資訊通訊網，但還是有極限的。"
L14_1.m_Talk_THA = "เรายังทำได้แค่รบกวนเส้นทางสื่อสารของพวกมัน"
L14_1.m_Talk_VTN = "Chúng ta chỉ có thể làm được bấy nhiêu bằng cách gây nhiễu đường dây liên lạc của họ."
L14_1.m_Talk_SCN = "就算是在干扰信息通讯网，也还是有限度的。"
L14_1.m_Talk_DEU = "Es reicht nicht aus, ihre Kommunikationswege zu stören."
L14_1.m_Talk_FRA = "On a fait ce qu'on a pu en perturbant leurs lignes de communication."
L15_1 = {}
