L17_1.m_Talk_ENG = "but if Queen shows up, that's the end of this operation."
L17_1.m_Talk_TWN = "但要是女皇出現的話，這個作戰就完了。"
L17_1.m_Talk_THA = "แต่ถ้าเป็นควีน ปฏิบัติการนี้ก็จบเห่เลยนะ"
L17_1.m_Talk_VTN = "nhưng nếu Quân Hậu xuất hiện, tác chiến này sẽ chấm dứt."
L17_1.m_Talk_SCN = "要是女王出现了的话，作战就完了。"
L17_1.m_Talk_DEU = "Aber wenn Queen auftaucht, ist es das Ende dieser Operation."
L17_1.m_Talk_FRA = "mais si c'est la reine qui se pointe, alors c'est la fin de cette opération."
