L18_1.m_Crash = 20
L18_1.m_Talk_KOREA = "퀸이라는 녀석이 그렇게 강해......?"
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "クイーンとやらは、そんなに強いの……？"
L18_1.m_Talk_ENG = "Exactly how strong is Queen?"
L18_1.m_Talk_TWN = "那個叫女皇的人這麼強嗎……？"
L18_1.m_Talk_THA = "ควีนแข็งแกร่งแค่ไหน?"
L18_1.m_Talk_VTN = "Chính xác thì Quân Hậu mạnh đến mức nào?"
L18_1.m_Talk_SCN = "女王那家伙那么强吗……？"
L18_1.m_Talk_DEU = "Wie stark ist Queen eigentlich genau?"
L18_1.m_Talk_FRA = "Elle est si forte que ça, cette reine ?"
L19_1 = {}
L19_1.m_CutScenKey_Talk = "EP5_ACT3_STAGE4_END@19#Talk"
L19_1.m_CutScenProcessKey = 19
L19_1.m_CutScenID = 185
L19_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L19_1.m_Pos = "L"
L19_1.m_Talk_KOREA = "네가 이렇게 자신 없는 말을 하는 건 처음 보는 것 같은데......"
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "あんたがそこまで弱気なことを言うのは初めてかも……"
L19_1.m_Talk_ENG = "I've never heard you sound so concerned about an enemy."
L19_1.m_Talk_TWN = "妳好像還是第一次說出這麼沒自信的話呢……"
L19_1.m_Talk_THA = "ฉันไม่เคยได้ยินเธอดูกังวลเรื่องศัตรูขนาดนี้เลย"
L19_1.m_Talk_VTN = "Tôi chưa bao giờ thấy bạn để ý đến kẻ thù như vậy."
L19_1.m_Talk_SCN = "我还是第一次听你说这么没有自信的话呢……"
L19_1.m_Talk_DEU = "Ich habe dich noch nie wegen eines Feindes so besorgt klingen hören."
L19_1.m_Talk_FRA = "Je t'avais encore jamais vue si préoccupée par un ennemi."
