L21_1 = {}
L21_1.m_CutScenKey_Talk = "EP5_ACT3_STAGE4_END@21#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 185
L21_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_Face = "UNIT_SERIOUS"
L21_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L21_1.m_Pos = "L"
L21_1.m_Crash = 40
L21_1.m_Talk_KOREA = "뭐, 뭐야. 그 기분 나쁜 눈빛은?"
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "な、何よ、その冷たい眼差しは。"
L21_1.m_Talk_ENG = "W-what? What's that look?"
L21_1.m_Talk_TWN = "幹、幹嘛。這個讓人不舒服的眼神？"
L21_1.m_Talk_THA = "อะ-อะไรกัน? ทำไมทำหน้าแบบนั้น?"
L21_1.m_Talk_VTN = "C-cái gì? Cái nhìn đó là sao?"
L21_1.m_Talk_SCN = "什，什么啊。干嘛这样看着我？"
L21_1.m_Talk_DEU = "W-was ist? Was soll dieser Blick?"
L21_1.m_Talk_FRA = "Q-Quoi ? Pourquoi tu me regardes comme ça ?"
L22_1 = {}
L22_1.m_CutScenKey_Talk = "EP5_ACT3_STAGE4_END@22#Talk"
L22_1.m_CutScenProcessKey = 22
L22_1.m_CutScenID = 185
L22_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L22_1.m_Pos = "R"
L22_1.m_Talk_KOREA = "아니, 그냥. 한심한 건 너인데 왜 내가 부끄러워해야 하는 건가 싶어서."
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "いや、どうしてこんなにもわからず屋なのか、情けなくなってきてね。"
L22_1.m_Talk_ENG = "Oh, I was just wondering. Why should I be the embarrassed one when you are the pathetic one?"
L22_1.m_Talk_TWN = "沒有，可悲的明明是妳，為什麼是我要覺得丟臉啊？"
L22_1.m_Talk_THA = "อ๋อ ฉันก็แค่นึกสงสัยน่ะ ว่าทำไมฉันต้องเป็นคนที่รู้สึกอาย ทั้งที่เธอเป็นคนน่าสมเพช?"
L22_1.m_Talk_VTN = "Ồ, tôi chỉ đang tự hỏi. Tại sao tôi phải là người xấu hổ khi bạn mới là người đáng thương?"
L22_1.m_Talk_SCN = "没什么。只是觉得泄气的明明是你，为什么我要觉得不好意思啊。"
L22_1.m_Talk_DEU = "Ach, ich habe mich nur gefragt, warum mir so oft Dinge peinlich sind, obwohl du weit peinlichere Fragen stellst …"
L22_1.m_Talk_FRA = "Oh, je me demandais juste. Pourquoi c'est moi qui devrais avoir l'air embarrassée alors que c'est toi la personne pathétique ?"
