L25_1 = "UNIT_IDLE"
L24_1.m_Face = L25_1
L25_1 = "CUTSCENE_TALK_02"
L24_1.m_StartBGMFileName = L25_1
L24_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L24_1.m_Pos = "R"
L25_1 = "리플레이서 같은 테러 조직이 유지되기 위한 제 1조건이 뭐라고 생각해?"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "リプレイサーのようなテロ組織を保つための第1条件は何だと思う？"
L24_1.m_Talk_JPN = L25_1
L25_1 = "What do you think is the first rule of running a terrorist organization like the Replacer Syndicate?"
L24_1.m_Talk_ENG = L25_1
L25_1 = "妳覺得要維持克隆集團這種恐怖組織，最重要的條件是什麼嗎？"
L24_1.m_Talk_TWN = L25_1
L25_1 = "เธอคิดว่าอะไรคือกฎข้อแรกของการบริหารองค์กรผู้ก่อการร้ายอย่างรีเพลสเซอร์ซินดิเคต?"
L24_1.m_Talk_THA = L25_1
L25_1 = "Bạn nghĩ quy tắc đầu tiên để điều hành một tổ chức khủng bố như Nghiệp Đoàn Nhân Bản là gì?"
L24_1.m_Talk_VTN = L25_1
L25_1 = "你知道像克隆集团这样的恐怖组织得以维持的第一要件是什么吗？"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Was meinst du, nach welchem Prinzip eine terroristische Organisation wie das Replacer-Syndikat läuft?"
L24_1.m_Talk_DEU = L25_1
L25_1 = "À ton avis, c'est quoi la première règle à respecter quand on dirige une organisation terroriste comme le Syndicat des substituts ?"
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
