L26_1 = "그, 글쎄......? 뭔데?"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "さ、さあ……？　なんだろう？"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Uh... I'm not sure... What is it?"
L25_1.m_Talk_ENG = L26_1
L26_1 = "呃，這個……是什麼？"
L25_1.m_Talk_TWN = L26_1
L26_1 = "เอ้อ... ฉันไม่แน่ใจนะ... อะไรล่ะ?"
L25_1.m_Talk_THA = L26_1
L26_1 = "Uh... Tôi không chắc... Là gì cơ?"
L25_1.m_Talk_VTN = L26_1
L26_1 = "这，这个嘛……什么啊？"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Äh … Keine Ahnung … Nach welchem denn?"
L25_1.m_Talk_DEU = L26_1
L26_1 = "Euh... Je sais pas... C'est quoi ?"
L25_1.m_Talk_FRA = L26_1
