L27_1 = "EP5_ACT3_STAGE4_END@26#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 26
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 185
L26_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L26_1.m_Pos = "R"
L27_1 = "바로 직접적인 폭력 수단, 즉 힘이야."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "直接的な暴力、つまり武力だよ。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "It's a direct exhibition of force. In other words, violence."
L26_1.m_Talk_ENG = L27_1
L27_1 = "就是直接的暴力手段，也就是力量。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "การแสดงกำลังโดยตรงไง พูดอีกอย่างก็คือความรุนแรง"
L26_1.m_Talk_THA = L27_1
L27_1 = "Đó là một cuộc biểu diễn vũ lực trực tiếp. Nói cách khác, bạo lực."
L26_1.m_Talk_VTN = L27_1
L27_1 = "就是直接的暴力手段，也就是力量。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Es ist das Prinzip der Gewalt."
L26_1.m_Talk_DEU = L27_1
L27_1 = "La démonstration de force. En d'autres termes, la violence."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "EP5_ACT3_STAGE4_END@27#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 27
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 185
L27_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L27_1.m_Pos = "R"
L28_1 = "적을 공포에 떨게 만들고 배신자를 처단하고 조직원이 감히 의문을 품지 못하게 만드는 압도적인 힘."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "敵を恐怖に震え上がらせ、裏切り者は始末し、\n組織メンバーに絶大な信頼感を与える、圧倒的な力。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "They use violence to make enemies tremble, punish traitors, and keep the members in line."
L27_1.m_Talk_ENG = L28_1
L28_1 = "讓敵人瑟瑟發抖、除掉叛徒、使組織成員不敢質疑的壓倒性力量。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "พวกนั้นใช้ความรุนแรงเพื่อทำให้ศัตรูตัวสั่น ลงโทษคนทรยศ และทำให้สมาชิกไม่แตกแถว"
L27_1.m_Talk_THA = L28_1
L28_1 = "Họ sử dụng bạo lực để khiến kẻ thù run sợ, trừng phạt những kẻ phản bội và khiến các thành viên phải nghe lời."
L27_1.m_Talk_VTN = L28_1
L28_1 = "让敌人瑟瑟发抖、内部人员不敢背叛的压倒性的力量。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Sie setzen Gewalt ein, um ihre Feinde zum Zittern zu bringen, Verräter zu bestrafen und die Mitglieder bei der Stange zu halten."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Ils utilisent la violence pour faire trembler leurs ennemis, punir les traîtres et garder leurs membres dans le rang."
L27_1.m_Talk_FRA = L28_1
