L29_1.m_Pos = "R"
L30_1 = "리플레이서 5대 간부라는 것도 웃기는 소리야."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "5大リプレイサー幹部っていうのも笑わせるわ。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "The five officers of the Replacers? What a joke."
L29_1.m_Talk_ENG = L30_1
L30_1 = "所謂克隆集團5大幹部都挺搞笑的。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "เจ้าหน้าที่ทั้งห้าแห่งรีเพลสเซอร์เหรอ? เรื่องตลกชัดๆ"
L29_1.m_Talk_THA = L30_1
L30_1 = "Năm sĩ quan Người Nhân Bản? Thật là một câu chuyện hài hước."
L29_1.m_Talk_VTN = L30_1
L30_1 = "所谓克隆集团5大头目挺搞笑的。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Die fünf Replacer-Offiziere sind eher ein Witz."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Les cinq officiers des substituts ? Une vaste blague."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "EP5_ACT3_STAGE4_END@30#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L30_1.m_CutScenProcessKey = 30
L30_1.m_CutScenID = 185
L30_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L30_1.m_Pos = "R"
L31_1 = "설립자인 킹을 제외하면 나머지 간부들은 사실상 퀸이 발굴하고 키워낸 녀석들이라고."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "設立者のキングを除けば、残りの幹部は事実上、クイーンが発掘して育てた奴らだからね。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Except for King, the founder, all the rest were actually discovered and reared by Queen."
L30_1.m_Talk_ENG = L31_1
L31_1 = "除了創立者的帝皇之外，剩下的幹部實際上，都是女皇發掘並培養出來的人。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ยกเว้นคิงซึ่งเป็นผู้ก่อตั้ง คนอื่นๆ ถูกค้นพบและคัดสรรโดยควีน"
L30_1.m_Talk_THA = L31_1
L31_1 = "Ngoại trừ Quân Vua, người sáng lập, tất cả những người còn lại đều được Quân Hậu phát hiện và dạy dỗ."
L30_1.m_Talk_VTN = L31_1
L31_1 = "除了创立者王之外，剩下的头目实际上都是女王发掘和培养出来的。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Mit Ausnahme von King, dem Gründer, wurden alle anderen von Queen entdeckt und groß gemacht."
L30_1.m_Talk_DEU = L31_1
L31_1 = "À l'exception du roi, le fondateur, tous les autres ont été recrutés et formés par la reine."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "EP5_ACT3_STAGE4_END@31#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 31
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 185
L31_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L31_1.m_Pos = "R"
L32_1 = "반란이나 항명 따위는 전혀 걱정하지 않고 자신과 동격의 간부들을 키워내는 그 자신감이 대체 어디서 나온다고 생각해?"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "反逆などをまったく気にせず、自分と同格の幹部を育成する。その自信はどこから来てると思う？"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Why do you think Queen can keep discovering talents and place them in officer positions without worrying about rebellion or disobedience?"
L31_1.m_Talk_ENG = L32_1
L32_1 = "妳覺得她到底哪來的自信，完全不擔心叛亂和反抗，刻意培育出與自己同級的幹部？"
L31_1.m_Talk_TWN = L32_1
L32_1 = "เธอคิดว่าทำไมควีนถึงสามารถค้นพบคนเก่งๆ ได้เรื่อยๆ แล้วก็มอบตำแหน่งเจ้าหน้าที่ให้โดยไม่ต้องกังวลว่าพวกเขาจะกบฏหรือแข็งข้อล่ะ?"
L31_1.m_Talk_THA = L32_1
L32_1 = "Bạn nghĩ tại sao Quân Hậu có thể tiếp tục phát hiện nhân tài và phong cho họ các vị trí sĩ quan mà không cần lo lắng về việc nổi loạn hoặc bất tuân?"
L31_1.m_Talk_VTN = L32_1
L32_1 = "你觉得她培养这些和自己同级但又完全不需要担心叛乱和反抗的头目们，她的底气何在？"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Und was glaubst du: Wie kann Queen immer wieder Talente entdecken und sie in leitende Positionen bringen, ohne Rebellion oder Ungehorsam fürchten zu müssen?"
L31_1.m_Talk_DEU = L32_1
L32_1 = "Pourquoi penses-tu que la reine peut recruter de nouveaux talents et les placer aux postes d'officier sans craindre leur désobéissance ou une rébellion ?"
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "EP5_ACT3_STAGE4_END@32#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 32
L32_1.m_CutScenProcessKey = L33_1
