L32_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L32_1.m_Pos = "L"
L33_1 = "다른 간부들이...... 전부 덤벼들어도 이길 수 있으니까?"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "他の幹部が……全員かかってきても、勝てる自信があるから？"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Because she's stronger than all of the others combined?"
L32_1.m_Talk_ENG = L33_1
L33_1 = "因為其他幹部……一起上也打不贏她？"
L32_1.m_Talk_TWN = L33_1
L33_1 = "เพราะเธอแข็งแกร่งกว่าคนอื่นๆ ทุกคนรวมกันเหรอ?"
L32_1.m_Talk_THA = L33_1
L33_1 = "Vì cô ấy mạnh hơn tất cả những người khác cộng lại?"
L32_1.m_Talk_VTN = L33_1
L33_1 = "因为其他头目……一起上也打不赢她？"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Weil sie stärker ist als alle anderen zusammen?"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Parce qu'elle est plus puissante que tous les autres réunis ?"
L32_1.m_Talk_FRA = L33_1
