L35_1 = "리플레이서 융합체와 침식체 등급의 1:1 비교가 정확하지는 않지만......"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "リプレイサー融合体と侵食体ランクの比較が正確とは言えないけれど……"
L34_1.m_Talk_JPN = L35_1
L35_1 = "We really can't compare a Replacer hybrider to a C.O. one for one,"
L34_1.m_Talk_ENG = L35_1
L35_1 = "把克隆融合體和侵蝕體分級做1:1的比較雖然不太準確……"
L34_1.m_Talk_TWN = L35_1
L35_1 = "เราเตรียมรีเพลสเซอร์ประเภทไฮบริเดอร์กับวัตถุคอร์รัปต์แบบโดดๆ ไม่ได้นะ"
L34_1.m_Talk_THA = L35_1
L35_1 = "Chúng ta thực sự không thể so sánh một Người Lai Tạo Nhân Bản với một V.T.B.A.M một đổi một,"
L34_1.m_Talk_VTN = L35_1
L35_1 = "虽然克隆融合体和侵蚀体等级的比例不是准确的1:1……"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Man kann Replacer-Hybriden nicht direkt mit C. O.s vergleichen,"
L34_1.m_Talk_DEU = L35_1
L35_1 = "On peut pas réellement comparer un hybride substitut avec un O.C.,"
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "EP5_ACT3_STAGE4_END@35#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 35
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 185
L35_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
