L35_1.m_Pos = "R"
L36_1 = "각국 정보부에서 리플레이서 퀸은 4종 침식체와 동급의 위험요소로 평가 받고 있다고."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "各国の情報局でリプレイサー・クイーンは、第4種侵食体と同等の危険因子として評価されてるの。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "but intelligence agencies all over the world estimate that Replacer Queen is as dangerous as a Category 4 C.O."
L35_1.m_Talk_ENG = L36_1
L36_1 = "但在各國情報部的評價中，女皇和4級侵蝕體同樣危險。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "แต่หน่วยข่าวกรองทั่วโลกประเมินว่ารีเพลสเซอร์ ควีนนี้อันตรายพอๆ กับวัตถุคอร์รัปต์คลาส 4"
L35_1.m_Talk_THA = L36_1
L36_1 = "nhưng các cơ quan tình báo trên toàn thế giới đánh giá rằng Quân Hậu Nhân Bản cũng nguy hiểm như một V.T.B.A.M Hạng 4"
L35_1.m_Talk_VTN = L36_1
L36_1 = "但是各国情报部评价女皇具有等同于4级侵蚀体的危险要素。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "aber Geheimdienste auf der ganzen Welt halten Replacer-Queen für so gefährlich wie ein C. O. der Kategorie 4."
L35_1.m_Talk_DEU = L36_1
L36_1 = "mais les services de renseignements du monde entier estiment que la reine des substituts est aussi dangereuse qu'un O.C. catégorie 4."
L35_1.m_Talk_FRA = L36_1
