L38_1 = "이쯤 설명했으면 너도 알아들었겠지?"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "そろそろわかってきたでしょ？"
L37_1.m_Talk_JPN = L38_1
L38_1 = "So, I assume you now understand why I've become all edgy"
L37_1.m_Talk_ENG = L38_1
L38_1 = "說到這裡，妳應該也明白了吧？"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ฉันว่าเธอคงเข้าใจแล้วนะว่าทำไมฉันถึงตื่นตัวนัก"
L37_1.m_Talk_THA = L38_1
L38_1 = "Vì vậy, tôi nghĩ bây giờ bạn đã hiểu tại sao tôi trở nên khó chịu"
L37_1.m_Talk_VTN = L38_1
L38_1 = "说到这里你应该也明白了吧？"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Ich nehme an, du verstehst jetzt, warum ich jedes Mal aufschrecke"
L37_1.m_Talk_DEU = L38_1
L38_1 = "Voilà, je pense que tu comprends pourquoi je suis un peu à cran,"
L37_1.m_Talk_FRA = L38_1
