L38_1.m_Pos = "R"
L39_1 = "내가 왜 퀸의 이야기만 나오면 물 맞은 고양이처럼 경기를 일으키는지......"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "どうして私が急いでいるのか……"
L38_1.m_Talk_JPN = L39_1
L39_1 = "like a cat that heard a dish break when someone brings up Queen."
L38_1.m_Talk_ENG = L39_1
L39_1 = "為什麼聽到女皇的事情，我就像驚弓之鳥一樣……"
L38_1.m_Talk_TWN = L39_1
L39_1 = "เหมือนแมวที่ได้ยินเสียงจานแตกเวลาใครพูดถึงควีนขึ้นมา"
L38_1.m_Talk_THA = L39_1
L39_1 = "giống như một chú mèo khi nghe thấy tiếng đĩa vỡ nếu ai đó nhắc tới Quân Hậu."
L38_1.m_Talk_VTN = L39_1
L39_1 = "为什么我听到和女皇相关的事情就像那个惊弓之鸟一样……"
L38_1.m_Talk_SCN = L39_1
L39_1 = "wie eine Katze, wenn ein Teller zerbricht, sobald Queen erwähnt wird."
L38_1.m_Talk_DEU = L39_1
L39_1 = "dès que quelqu'un mentionne la reine."
L38_1.m_Talk_FRA = L39_1
