L39_1.m_Pos = "R"
L40_1 = "내 생각엔...... 힐데 소대장이라고 해도 정면으로 싸워 이기는 건 무리일 거야."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "たぶん……ヒルデ小隊長でも真っ向勝負では勝てないと思う。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Personally, I don't think even Commander Hilde could defeat her head on."
L39_1.m_Talk_ENG = L40_1
L40_1 = "根據我的推測……就算是希爾德小隊長，正面對決都無法取勝。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ส่วนตัวแล้วฉันว่าต่อให้เป็นผู้บัญชาการฮิลเด้ก็ไม่สามารถเอาชนะเธอซึ่งๆ หน้าได้"
L39_1.m_Talk_THA = L40_1
L40_1 = "Cá nhân tôi không nghĩ ngay cả Tổng Tư Lệnh Hilde cũng có thể đánh bại cô ta."
L39_1.m_Talk_VTN = L40_1
L40_1 = "在我看来……就算是希尔德队长正面进攻的胜算都不大。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Ich persönlich glaube, dass selbst Kommandantin Hilde sie nicht direkt besiegen könnte."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Personnellement, je pense que même la commandante Hilde ne serait pas capable de la vaincre en face à face."
L39_1.m_Talk_FRA = L40_1
