L42_1.m_Pos = "L"
L43_1 = "그러고 보니 그 퀸이라는 녀석과 개인적인 친분이라도 있는 거야?"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "そういえば、そのクイーンとやらとは何か個人的な繫がりでもあるの？"
L42_1.m_Talk_JPN = L43_1
L43_1 = "By the way, are you personally acquainted with Queen?"
L42_1.m_Talk_ENG = L43_1
L43_1 = "話說，妳和那個叫女皇的人好像有什麼關係？"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ว่าแต่เธอสนิทกับควีนเป็นการส่วนตัวรึเปล่า?"
L42_1.m_Talk_THA = L43_1
L43_1 = "Nhân tiện, bạn có quen với Quân Hậu không?"
L42_1.m_Talk_VTN = L43_1
L43_1 = "话说你和女皇那个家伙还有点私交？"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Hast du eigentlich eine persönliche Beziehung mit Queen?"
L42_1.m_Talk_DEU = L43_1
L43_1 = "Au fait, tu la connais personnellement, la reine ?"
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "EP5_ACT3_STAGE4_END@43#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 43
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 185
L43_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
