L43_1.m_fWaitTime = 0
L43_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L43_1.m_Pos = "L"
L44_1 = "너와는 꽤 잘 알고 있는 눈치던데......?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "あんたのこと、よくわかってるような素振りを見せてたけど……？"
L43_1.m_Talk_JPN = L44_1
L44_1 = "She seemed to know you pretty well."
L43_1.m_Talk_ENG = L44_1
L44_1 = "妳好像非常瞭解她的樣子……？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ควีนดูจะรู้จักเธอดี"
L43_1.m_Talk_THA = L44_1
L44_1 = "Cô ấy dường như biết bạn khá rõ."
L43_1.m_Talk_VTN = L44_1
L44_1 = "感觉你们互相都挺了解啊……？"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Sie schien dich ziemlich gut zu kennen."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Elle avait l'air de bien te connaître."
L43_1.m_Talk_FRA = L44_1
