L46_1 = "UNIT_IDLE"
L45_1.m_Face = L46_1
L45_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L45_1.m_Pos = "R"
L46_1 = "뭐, 언젠가는 알게 될 내용이니까 지금 미리 이야기해주는 게 나을지도 모르겠네."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "まあ、いつかはわかる日が来るだろうから、今ここで教えたほうがいいか。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Well, you're going to find out eventually. I might as well tell you now."
L45_1.m_Talk_ENG = L46_1
L46_1 = "嘛，反正總要知道的，事先告訴妳說不定會比較好。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "เดี๋ยวเธอก็จะรู้คำตอบเองนั่นละ ฉันจะบอกเธอตอนนี้เลยก็ได้นะ"
L45_1.m_Talk_THA = L46_1
L46_1 = "Chà, cuối cùng bạn sẽ biết. Tôi cũng có thể nói với bạn ngay bây giờ."
L45_1.m_Talk_VTN = L46_1
L46_1 = "嗯，反正总要知道的，现在就告诉你也行。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Irgendwann wirst du es ohnehin herausfinden, also kann ich es dir auch gleich sagen …"
L45_1.m_Talk_DEU = L46_1
L46_1 = "Eh bien, tu vas finir par le découvrir, donc autant te le dire tout de suite."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "EP5_ACT3_STAGE4_END@46#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 46
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 185
