L46_1.m_Pos = "R"
L47_1 = "우리가...... 알트 소대가 리플레이서 출신이라는 건 알고 있지?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "私たち……アルト小隊がリプレイサー出身なのは知ってるよね？"
L46_1.m_Talk_JPN = L47_1
L47_1 = "You know that we, the ALT Squad, were once in the Syndicate, don't you?"
L46_1.m_Talk_ENG = L47_1
L47_1 = "我們……阿爾特小隊是克隆集團出身的，這件事妳知道吧？"
L46_1.m_Talk_TWN = L47_1
L47_1 = "เธอก็รู้ว่าหน่วย ALT เคยอยู่ในซินดิเคตใช่ไหม?"
L46_1.m_Talk_THA = L47_1
L47_1 = "Bạn biết rằng chúng ta, Tiểu Đội ALT, đã từng ở trong Nghiệp Đoàn phải không?"
L46_1.m_Talk_VTN = L47_1
L47_1 = "我们……阿尔特小队是从克隆集团出来的，你知道吧？"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Du weißt, dass wir, also der ALT-Trupp, einmal Teil des Syndikats waren, oder nicht?"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Tu sais que nous, l'escouade ALT, faisions partie du Syndicat avant, n'est-ce pas ?"
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
