L48_1.m_Pos = "R"
L49_1 = "정확히 말하면 우린 리플레이서가 아닌 리플레이서 실험체 출신이야."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "厳密に言うと、私たちはリプレイサーじゃなくて、リプレイサー実験体出身なの。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "To be precise, we weren't exactly Replacers. We were test subjects."
L48_1.m_Talk_ENG = L49_1
L49_1 = "正確來說，我們不是克隆集團，而是克隆集團實驗體出身。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "พูดให้ชัดคือ เราไม่ใช่รีเพลสเซอร์จริงๆ แต่เป็นตัวทดลอง"
L48_1.m_Talk_THA = L49_1
L49_1 = "Nói chính xác, chúng ta không phải là Người Nhân Bản chính xác. Chúng ta là đối tượng thử nghiệm."
L48_1.m_Talk_VTN = L49_1
L49_1 = "准确的说不是克隆集团，是克隆集团试验体。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Um genau zu sein, waren wir nicht wirklich Replacer, sondern Testsubjekte."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Pour être plus précise, on était pas des substituts. On était des cobayes."
L48_1.m_Talk_FRA = L49_1
