L2_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L3_1 = "내가 가진 첫 번째 기억은...... 차가운 실험대 위에 누워 있는 내 모습이었어."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "私が持ってる最初の記憶は……冷たい実験台に横たわっている自分の姿。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "The first memory I have is lying on the cold lab table."
L2_1.m_Talk_ENG = L3_1
L3_1 = "我最初的記憶……是我躺在冰冷實驗臺上的樣子。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ความทรงจำแรกของฉันคือการนอนอยู่บนโต๊ะในห้องทดลองเย็นๆ"
L2_1.m_Talk_THA = L3_1
L3_1 = "Ký ức đầu tiên tôi có là nằm trên chiếc bàn thí nghiệm lạnh lẽo."
L2_1.m_Talk_VTN = L3_1
L3_1 = "我记得的第一件事就是……我躺在冰冷的实验台上的样子。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Die erste Erinnerung, die ich habe, ist, dass ich auf dem kalten Labortisch lag."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Mon tout premier souvenir est d'être étendue sur une table de laboratoire glacée."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "EP5_ACT3_STAGE4_END@53#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 53
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 185
L3_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L4_1 = "내가 누구였는지, 어디에 살았는지, 원래 이름은 뭐였는지......"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "私は誰なのか、どこに住んでいたのか、元々の名前はなんだったのか……"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Who I was, where I came from, what my real name was..."
L3_1.m_Talk_ENG = L4_1
L4_1 = "我是誰、住在哪裡、原本的名字叫什麼……"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ฉันเป็นใคร มาจากไหน ชื่อจริงคืออะไร..."
L3_1.m_Talk_THA = L4_1
L4_1 = "Tôi là ai, tôi đến từ đâu, tên thật của tôi là gì..."
L3_1.m_Talk_VTN = L4_1
L4_1 = "我是谁，我的家乡在哪里，我叫什么名字……"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Wer ich war, woher ich kam, was mein richtiger Name war …"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Qui j'étais, d'où je venais, quel était mon véritable nom..."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "EP5_ACT3_STAGE4_END@54#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 54
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 185
