L4_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L5_1 = "그런 기억은 아무것도 없어."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "そんな記憶は何もないの。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "I couldn't remember anything."
L4_1.m_Talk_ENG = L5_1
L5_1 = "什麼記憶也沒有。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ฉันจำอะไรไม่ได้เลย"
L4_1.m_Talk_THA = L5_1
L5_1 = "Tôi không thể nhớ bất cứ điều gì."
L4_1.m_Talk_VTN = L5_1
L5_1 = "我都不记得。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "An all das konnte ich mich nicht erinnern."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Impossible de me souvenir de quoi que ce soit."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
