L6_1 = "무슨...... 설마 납치라도 당한 거야?"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "それはどういう……まさか、さらわれたとか？"
L5_1.m_Talk_JPN = L6_1
L6_1 = "No... Did they kidnap you or something?"
L5_1.m_Talk_ENG = L6_1
L6_1 = "什麼……該不會是被綁架了吧？"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ไม่นะ... พวกเขาลักพาตัวเธอเหรอ?"
L5_1.m_Talk_THA = L6_1
L6_1 = "Không ... Họ đã bắt cóc bạn hay sao?"
L5_1.m_Talk_VTN = L6_1
L6_1 = "怎么可能……难道是被绑架了吗？"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Nein … Warst du entführt worden oder so?"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Non... Ils vous ont enlevées ou quelque chose du genre ?"
L5_1.m_Talk_FRA = L6_1
