L7_1 = "EP5_ACT3_STAGE4_END@56#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 56
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 185
L6_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L7_1 = "몰라. 실험의 부작용인지 뭔지, 그 이전의 기억은 아무것도 나지 않으니까."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "わからない。実験の副作用なのか、それ以前の記憶がまったくないの。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "I don't know. I don't know if it's the side effects of the experiment, but I lost all my previous memories."
L6_1.m_Talk_ENG = L7_1
L7_1 = "不知道。不知道是因為實驗的副作用還是什麼，那之前的記憶完全想不起來。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ฉันไม่รู้ ฉันไม่รู้ว่ามันคือผลข้างเคียงของการทดลองรึเปล่า แต่ฉันสูญเสียความทรงจำก่อนหน้านั้นไปหมดเลย"
L6_1.m_Talk_THA = L7_1
L7_1 = "Tôi không biết. Tôi không biết đó có phải là tác dụng phụ của thí nghiệm hay không, nhưng tôi đã mất tất cả ký ức trước đây của mình."
L6_1.m_Talk_VTN = L7_1
L7_1 = "不知道。不知道是不是因为实验的副作用，那以前的事情完全不记得。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Ich weiß es nicht … Und ich weiß nicht, ob es die Nebenwirkungen des Experiments sind – aber ich habe all meine früheren Erinnerungen verloren."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Je sais pas. Je sais pas si c'est à cause de leurs expériences, mais j'ai perdu tous mes souvenirs antérieurs."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "EP5_ACT3_STAGE4_END@57#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 57
