L8_1 = "한때는 부모님을 찾고 싶다는 마음도 있었지만...... 그런 희망은 버린 지 오래야."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "一時は実の親を探したい気持ちもあったけど……そんな希望はとっくに捨てたわ。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "I once thought I wanted to find my parents, but I gave up on that a long time ago."
L7_1.m_Talk_ENG = L8_1
L8_1 = "以前，我也想過要去找自己的父母……但這個希望也放棄很久了。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ครั้งหนึ่งฉันเคยคิดอยากตามหาพ่อแม่ แต่ฉันก็ยอมแพ้ไปนานแล้ว"
L7_1.m_Talk_THA = L8_1
L8_1 = "Tôi đã từng nghĩ rằng tôi muốn tìm cha mẹ của mình, nhưng tôi đã từ bỏ điều đó từ rất lâu rồi."
L7_1.m_Talk_VTN = L8_1
L8_1 = "我也想过找自己的父母……但也早就放弃了。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Ich dachte früher, dass ich meine Eltern finden wollte … Aber das habe ich schon vor langer Zeit aufgegeben."
L7_1.m_Talk_DEU = L8_1
L8_1 = "J'ai cru que je voulais retrouver mes parents, mais j'ai abandonné cette idée depuis longtemps."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
