L10_1 = "어쨌든 그곳은 실험실이자, 일종의 선별 장소였어."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "とにかく、そこは実験室で、ある種の選別場所でもあったの。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Anyway, the place was a lab, and at the same time a testing ground."
L9_1.m_Talk_ENG = L10_1
L10_1 = "不管怎樣，那裡既是實驗室，還是一種選拔的場所。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "เอาละ สถานที่นั้นเป็นห้องทดลอง และก็เป็นทั้งลานทดสอบไปพร้อมๆ กัน"
L9_1.m_Talk_THA = L10_1
L10_1 = "Dù sao thì nơi đó cũng là một phòng thí nghiệm, đồng thời cũng là một bãi thử nghiệm."
L9_1.m_Talk_VTN = L10_1
L10_1 = "不管怎样，那里既是实验室，还是一种筛选的场所。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Auf jeden Fall war der Ort nicht nur ein Labor, sondern auch eine Art Testgelände."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Bref, c'était un laboratoire mais également un terrain d'essai."
L9_1.m_Talk_FRA = L10_1
