L15_1 = "그래, 과목도 다양했어."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "そう、色んなテストがあったのよ。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Yes, of various things."
L14_1.m_Talk_ENG = L15_1
L15_1 = "沒錯，篩選的科目也很多樣。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ใช่ ทดสอบอะไรหลายๆ อย่าง"
L14_1.m_Talk_THA = L15_1
L15_1 = "Đúng, của rất nhiều thứ khác nhau."
L14_1.m_Talk_VTN = L15_1
L15_1 = "没错，种类也不一样。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Ja, für verschiedene Dinge."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Oui, pour plein de choses."
L14_1.m_Talk_FRA = L15_1
