L15_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L16_1 = "간단한 IQ 테스트부터 약물검사, 전투 훈련, 생존 경쟁까지......"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "簡単なIQテストから、薬物検査、戦闘訓練、勝ち抜きテストまで……"
L15_1.m_Talk_JPN = L16_1
L16_1 = "We did simple IQ tests, chemical experiments, combat training, survival free-for-alls..."
L15_1.m_Talk_ENG = L16_1
L16_1 = "從簡單的IQ測試，到藥物檢測、戰鬥訓練，到生存競爭……"
L15_1.m_Talk_TWN = L16_1
L16_1 = "เราทำการทดสอบ IQ ง่ายๆ การทดลองทางเคมี การฝึกต่อสู้ การแข่งกันเอาตัวรอด..."
L15_1.m_Talk_THA = L16_1
L16_1 = "Chúng tôi đã thực hiện các bài kiểm tra IQ đơn giản, thí nghiệm hóa học, huấn luyện chiến đấu, sinh tồn..."
L15_1.m_Talk_VTN = L16_1
L16_1 = "从简单的IQ测试，到药物检测、战斗训练，直到生存竞争……"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Wir vollführten einfache IQ-Tests, chemische Experimente, Kampfausbildung, Überlebenswettkämpfe …"
L15_1.m_Talk_DEU = L16_1
L16_1 = "On faisait de simples tests de QI, des essais de produits chimiques, de l'entraînement au combat, des épreuves de survie individuelles..."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
