L18_1 = "EP5_ACT3_STAGE4_END@67#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 67
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 185
L17_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L18_1 = "설마 같은 방 안에 몰아넣고 서로 죽이라고 시켰다거나......"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "まさか、同じ部屋に閉じ込めて、殺し合いをさせたとか？"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Did they put you all in the same room and make you kill each other?"
L17_1.m_Talk_ENG = L18_1
L18_1 = "難道是在同一個房間裡玩大逃殺嗎……"
L17_1.m_Talk_TWN = L18_1
L18_1 = "พวกนั้นให้พวกเธออยู่ในห้องเดียวกันแล้วก็ฆ่ากันเองเหรอ?"
L17_1.m_Talk_THA = L18_1
L18_1 = "Họ đã cho tất cả các bạn vào cùng một phòng và bắt các bạn giết nhau ư?"
L17_1.m_Talk_VTN = L18_1
L18_1 = "难道是聚在一个房间里然后相互残杀吗……"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Wurdet ihr alle in einen Raum gesteckt und gezwungen, euch gegenseitig umzubringen?"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Ils vous ont tous mis dans la même salle et vous ont obligés à vous entretuer ?"
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "EP5_ACT3_STAGE4_END@68#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 68
