L18_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L19_1 = "무슨 말도 안 되는 소리야? 무협지를 너무 많이 본 것 같은데?"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "そんなわけないでしょ、映画の見すぎじゃないの？"
L18_1.m_Talk_JPN = L19_1
L19_1 = "What are you talking about? You've been watching too many movies."
L18_1.m_Talk_ENG = L19_1
L19_1 = "這是什麼鬼話？武俠小說看太多了吧？"
L18_1.m_Talk_TWN = L19_1
L19_1 = "พูดอะไรของเธอ? ดูหนังมากเกินไปแล้วนะ"
L18_1.m_Talk_THA = L19_1
L19_1 = "Bạn đang nói về cái gì vậy? Bạn đã xem quá nhiều phim."
L18_1.m_Talk_VTN = L19_1
L19_1 = "怎么可能？武侠小说看多了吧？"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Was redest du da? Du hast zu viele Filme gesehen."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Qu'est-ce que tu racontes ? Tu regardes trop de films."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "EP5_ACT3_STAGE4_END@69#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 69
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 185
L19_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L20_1 = "사춘기도 안 지난 애들에게 그런 짓을 했다간 선별이고 뭐고 심리 쇼크로 자살하기 십상일걸?"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "思春期すら迎えてない子どもにそんなことさせてたら、\n選別どころか、トラウマで自殺する子が続出するわよ。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "We're talking about prepubescent kids here. Something like that would have destroyed their minds beyond recovery."
L19_1.m_Talk_ENG = L20_1
L20_1 = "讓連青春期都還沒到的小孩做那種事，還做什麼選拔，早就因為心理創傷而自殺了吧？"
L19_1.m_Talk_TWN = L20_1
L20_1 = "นี่เรากำลังพูดถึงเด็กวัยก่อนเจริญพันธุ์นะ เรื่องพรรค์นั้นคงทำลายจิตใจเกินเยียวยาแล้วละ"
L19_1.m_Talk_THA = L20_1
L20_1 = "Chúng tôi đang nói về trẻ em trước tuổi dậy thì ở đây. Một cái gì đó như thế sẽ phá hủy tâm trí của họ đến mức không thể phục hồi."
L19_1.m_Talk_VTN = L20_1
L20_1 = "让还在青春期的孩子们做那样的事情，还做什么筛选，会有孩子因为心理冲击自杀的吧？"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Wir waren damals vorpubertäre Kinder. So etwas hätte nicht wiedergutzumachenden Schaden angerichtet."
L19_1.m_Talk_DEU = L20_1
L20_1 = "C'était des enfants prépubères. Quelque chose comme ça aurait irrémédiablement anéanti leur esprit."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
