L22_1 = "EP5_ACT3_STAGE4_END@71#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 71
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 185
L21_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L22_1 = "하지만 뭐...... 아주 틀린 말도 아니지. 그때의 훈련 과정은......"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "でもまあ……あながち間違ってもいないかもね。当時の訓練過程は……"
L21_1.m_Talk_JPN = L22_1
L22_1 = "But... In a way, you're not entirely wrong. The training was..."
L21_1.m_Talk_ENG = L22_1
L22_1 = "但是……妳說得也沒有錯太多。當時的訓練課程……"
L21_1.m_Talk_TWN = L22_1
L22_1 = "แต่... ในแง่หนึ่งเธอก็ไม่ได้คิดผิดอย่างสิ้นเชิงนะ การฝึกนั้นก็คือ..."
L21_1.m_Talk_THA = L22_1
L22_1 = "Nhưng... Theo một cách nào đó, bạn không hoàn toàn sai. Khóa đào tạo..."
L21_1.m_Talk_VTN = L22_1
L22_1 = "但是呃……你说的也不错。当时训练……"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Aber … Du liegst nicht ganz falsch. Die Ausbildung war …"
L21_1.m_Talk_DEU = L22_1
L22_1 = "Mais... dans un sens, t'as pas tout à fait tort. L'entraînement était..."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "EP5_ACT3_STAGE4_END@72#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 72
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 185
L22_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L23_1 = "......아니, 이 이야긴 그만 할래."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "……いや、この話はここまでにしましょう。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "No, I don't want to talk about it anymore."
L22_1.m_Talk_ENG = L23_1
L23_1 = "……不。不說這個了。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ไม่เอา ฉันไม่อยากพูดถึงเรื่องนั้นแล้วละ"
L22_1.m_Talk_THA = L23_1
L23_1 = "Không, tôi không muốn nói về nó nữa."
L22_1.m_Talk_VTN = L23_1
L23_1 = "……不，不说这个了。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Nein, ich möchte nicht mehr darüber reden."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Non, j'ai pas envie d'en parler en fait."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "EP5_ACT3_STAGE4_END@73#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 73
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 185
