L24_1 = "어쨌든 선별 인원들은 몇 개의 조별로 활동했는데,"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "とにかく、選別されたメンバーはいくつかのチームに分かれて活動したんだけど、"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Anyway, we were divided in groups,"
L23_1.m_Talk_ENG = L24_1
L24_1 = "總之就是選拔人員分為幾個小組。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ก็นั่นละ เราถูกแบ่งออกเป็นกลุ่มๆ"
L23_1.m_Talk_THA = L24_1
L24_1 = "Dù sao, chúng ta đã được chia thành các nhóm,"
L23_1.m_Talk_VTN = L24_1
L24_1 = "总之就是筛选人员分为几个小组，"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Wie auch immer, wir wurden in Gruppen aufgeteilt."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Bref, on était séparés en plusieurs groupes,"
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "EP5_ACT3_STAGE4_END@74#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 74
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 185
L24_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L25_1 = "그곳에서 날 담당한 선별감독관이......"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "そこで私の担当になった選別監督官が……"
L24_1.m_Talk_JPN = L25_1
L25_1 = "and Replacer Queen was the overseer"
L24_1.m_Talk_ENG = L25_1
L25_1 = "在那裡負責我的選拔督察員……"
L24_1.m_Talk_TWN = L25_1
L25_1 = "และรีเพลสเซอร์ ควีนเป็นผู้ควบคุม"
L24_1.m_Talk_THA = L25_1
L25_1 = "và Quân Hậu Nhân Bản là người giám thị"
L24_1.m_Talk_VTN = L25_1
L25_1 = "在那里负责我的筛选督察员……"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Replacer-Queen war die Aufseherin,"
L24_1.m_Talk_DEU = L25_1
L25_1 = "et la reine des substituts était la surveillante"
L24_1.m_Talk_FRA = L25_1
