L28_1 = "바로 리플레이서 퀸이었어."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "まさにリプレイサー・クイーンだったの。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "that was in charge of my group."
L27_1.m_Talk_ENG = L28_1
L28_1 = "就是克隆．女皇。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ที่ดูแลกลุ่มของฉัน"
L27_1.m_Talk_THA = L28_1
L28_1 = " phụ trách nhóm của tôi."
L27_1.m_Talk_VTN = L28_1
L28_1 = "就是克隆·女皇。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "die für meine Gruppe zuständig war."
L27_1.m_Talk_DEU = L28_1
L28_1 = "en charge de mon groupe."
L27_1.m_Talk_FRA = L28_1
