L30_1 = "EP5_ACT3_STAGE4_END@79#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 79
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 185
L29_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L30_1 = "내 입으로 말하긴 그렇지만 선별 대상으로서의 내 성적은 꽤 괜찮은 편이었어."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "自分で言うのはあれだけど、選別メンバーとしての私の成績はかなり良い方だった。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Though I say it myself, my grades there were pretty good."
L29_1.m_Talk_ENG = L30_1
L30_1 = "雖然這是我自己說的，但作為選拔對象，我的成績非常好。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ถึงฉันจะไม่ควรพูดเองนะ แต่ฉันได้คะแนนดีทีเดียว"
L29_1.m_Talk_THA = L30_1
L30_1 = "Mặc dù tôi tự nói như vậy, nhưng điểm của tôi ở đó khá tốt."
L29_1.m_Talk_VTN = L30_1
L30_1 = "虽然我说出来有点奇怪，但是作为筛选对象的我成绩还算不错。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Man mag es kaum glauben, aber ich hatte dort ziemlich gute Noten."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Sans vouloir me vanter, mes notes étaient plutôt bonnes."
L29_1.m_Talk_FRA = L30_1
