L36_1 = "하지만 리플레이서 나이트 같은 머저리가 간부 후보생으로 뽑혀가는 와중에서도......"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "だけど、リプレイサー・ナイトみたいなマヌケも幹部候補生に選ばれたっていうのに……"
L35_1.m_Talk_JPN = L36_1
L36_1 = "But while morons like Replacer Knight were being picked out as officer candidates,"
L35_1.m_Talk_ENG = L36_1
L36_1 = "但當克隆．騎士那樣的笨蛋被選為幹部候補的時……"
L35_1.m_Talk_TWN = L36_1
L36_1 = "แต่ในขณะที่พวกโง่อย่างรีเพลสเซอร์ ไนท์ได้รับเลือกให้เป็นผู้ท้าชิงตำแหน่งเจ้าหน้าที่"
L35_1.m_Talk_THA = L36_1
L36_1 = "Nhưng trong khi những kẻ ngu ngốc như Quân Mã Nhân Bản được chọn làm ứng cử viên sĩ quan,"
L35_1.m_Talk_VTN = L36_1
L36_1 = "但是选拔克隆·骑士那些蠢货作为候补头目的时候……"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Aber während Idioten wie Replacer-Knight als Offiziersanwärter ausgewählt wurden,"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Mais pendant que les crétins comme le cavalier des substituts étaient sélectionnés en tant que candidats officiers,"
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
