L45_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L46_1 = "난 초조해졌어."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "私は焦りを感じるようになったの。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "and I was nervous."
L45_1.m_Talk_ENG = L46_1
L46_1 = "我開始焦急了起來。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "และฉันก็ประหม่า"
L45_1.m_Talk_THA = L46_1
L46_1 = "và tôi đã rất lo lắng."
L45_1.m_Talk_VTN = L46_1
L46_1 = "我开始焦虑。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "und ich wurde nervös."
L45_1.m_Talk_DEU = L46_1
L46_1 = "et j'avais peur."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "EP5_ACT3_STAGE4_END@96#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 96
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 185
L46_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L47_1 = "웃기는 이야기지만 그런 곳에서 몇 년을 지내고 나면 날 납치한 자들에 대한 분노보다, 인정받고 싶다는 경쟁심리가 생기게 되거든?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "おかしな話だけど、あんな場所で数年間暮らしてると、\n自分をさらった奴らへの怒りよりも、認められたいという承認欲求のほうが強くなっていくのよ。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "It may sound ridiculous, but year after year, the anger I had toward them for kidnapping me faded away and a weird drive for competition started to fill my mind."
L46_1.m_Talk_ENG = L47_1
L47_1 = "說來好笑，在那裡待了幾年之後，比起對綁架我的人感到憤怒，我反而產生了想要獲得他們認可的競爭心理。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "มันอาจฟังดูน่าขันนะ แต่ปีแล้วปีเล่า ความโกรธที่ฉันมีต่อการที่พวกเขาลักพาตัวฉันมาก็จางลง และในหัวของฉันก็เริ่มมีแต่แรงขับแปลกๆ ในการที่จะแข่งขัน"
L46_1.m_Talk_THA = L47_1
L47_1 = "Nghe có vẻ nực cười, nhưng năm này qua năm khác, sự tức giận mà tôi dành cho họ vì đã bắt cóc tôi biến mất dần và một động lực cạnh tranh kỳ lạ bắt đầu tràn ngập trong tâm trí tôi."
L46_1.m_Talk_VTN = L47_1
L47_1 = "说起来有点可笑，在那里呆了几年之后，我对绑架我的人没有愤怒，反而想获得他们的认可。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Es mag seltsam klingen, aber mit den Jahren verblasste die Wut, die ich für sie empfand, weil sie mich entführt hatten … Dafür begann eine Art Wettbewerbsdrang meinen Geist zu erfüllen."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Ça peut sembler ridicule, mais au fil des années, la colère que j'avais envers eux pour m'avoir kidnappée s'est estompée et un étrange désir de compétition a pris le dessus."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
