L49_1 = "EP5_ACT3_STAGE4_END@98#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 98
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 185
L48_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L49_1 = "그래서 노력했어."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "だから、努力し続けたの。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "So I worked hard."
L48_1.m_Talk_ENG = L49_1
L49_1 = "所以我開始努力。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ฉันเลยพยายามมาก"
L48_1.m_Talk_THA = L49_1
L49_1 = "Vì vậy, tôi đã làm việc chăm chỉ."
L48_1.m_Talk_VTN = L49_1
L49_1 = "所以我开始努力。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Ich arbeitete hart."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Donc j'ai travaillé dur."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "EP5_ACT3_STAGE4_END@99#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 99
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 185
L49_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L49_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L50_1 = "잠도 자지 않고, 상처 입은 짐승처럼 주변에 가시를 세우면서......"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "睡眠もとらず、傷ついた獣のように、周りをけん制しながら……"
L49_1.m_Talk_JPN = L50_1
L50_1 = "I barely slept. I was like an injured animal trying to look as fierce as possible."
L49_1.m_Talk_ENG = L50_1
L50_1 = "我不睡覺，像受傷的動物一樣警戒著周圍……"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ฉันแทบไม่ได้นอน ฉันเหมือนสัตว์บาดเจ็บที่พยายามทำตัวให้ดูดุร้ายที่สุด"
L49_1.m_Talk_THA = L50_1
L50_1 = "Tôi hầu như không ngủ. Tôi giống như một con thú bị thương cố gắng trông dữ tợn nhất có thể."
L49_1.m_Talk_VTN = L50_1
L50_1 = "我不睡觉，像受伤的动物一样警戒着周围……"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Ich schlief kaum. Ich war wie ein verletztes Tier, das versucht, möglichst wild auszusehen."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Je dormais à peine. J'étais un animal blessé qui essayait d'avoir l'air aussi féroce que possible."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "EP5_ACT3_STAGE4_END@100#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 100
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 185
L50_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L50_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L51_1 = "정말 죽을 힘을 다해 좋은 평가를 받기 위해 훈련에 매진했어."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "良い評価をもらうために、本当に死ぬ気で訓練に励んだわ。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "I did my damnedest to train myself, desperate to be in their favor."
L50_1.m_Talk_ENG = L51_1
L51_1 = "為了得到好的評價拼了命地訓練。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ฉันทำเต็มที่เพื่อฝึกฝนตัวเอง เพราะอยากจะเป็นคนที่พวกเขาโปรดปราน"
L50_1.m_Talk_THA = L51_1
L51_1 = "Tôi đã cố gắng hết sức để rèn luyện bản thân một cách tuyệt vọng để mang lại lợi ích cho họ."
L50_1.m_Talk_VTN = L51_1
L51_1 = "为了得到好的评价拼了命地训练。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Ich gab mein Bestes, um immer besser zu werden, denn ich wollte unbedingt hoch in ihrer Gunst stehen."
L50_1.m_Talk_DEU = L51_1
L51_1 = "J'ai fait de mon mieux pour m'entraîner, désespérée d'attirer enfin leur attention."
L50_1.m_Talk_FRA = L51_1
