L5_1 = "EP5_ACT3_STAGE4_END@104#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 104
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 185
L4_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L5_1 = "최종 테스트인 팀 별 모의 전투에서...... 결국 팀원이 모두 당하고, 난 쓰러지고 말았지."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "最終テストである、チーム対抗の模擬戦闘で……\nチームメンバー全員がやられ、私は倒れてしまったの。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "The day of mock combat, the final test, came, and all my teammates fell, just like I did."
L4_1.m_Talk_ENG = L5_1
L5_1 = "在最終測驗的小組模擬戰中……組員全被擊敗，而我也倒下了。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "วันแห่งการต่อสู้จำลองซึ่งเป็นการทดสอบครั้งสุดท้ายมาถึง และสมาชิกในทีมทุกคนสอบตก ฉันก็ด้วย"
L4_1.m_Talk_THA = L5_1
L5_1 = "Ngày chiến đấu giả, bài kiểm tra cuối cùng đã đến, và tất cả đồng đội của tôi đều ngã xuống, giống như tôi."
L4_1.m_Talk_VTN = L5_1
L5_1 = "在最终测试的小组模拟战斗中……组员都受伤了，我最后也倒下了。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Es kam der Tag des Scheingefechts, die letzte Prüfung. All meine Teamkameraden und ich versagten."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Le jour du combat à blanc, le test final, mes camarades ont échoué, tout comme moi."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "EP5_ACT3_STAGE4_END@105#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 105
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 185
L5_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L6_1 = "제대로 싸워 보지도 못했어."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "ろくに戦うこともできなかった。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "In fact, I never got a chance to fight."
L5_1.m_Talk_ENG = L6_1
L6_1 = "連好好戰鬥都沒辦法。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "อันที่จริงฉันไม่มีโอกาสได้สู้เลยด้วยซ้ำ"
L5_1.m_Talk_THA = L6_1
L6_1 = "Thực tế, tôi không bao giờ có cơ hội chiến đấu."
L5_1.m_Talk_VTN = L6_1
L6_1 = "都没能好好战斗。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Tatsächlich hatte ich nicht einmal gekämpft …"
L5_1.m_Talk_DEU = L6_1
L6_1 = "En réalité, j'ai même pas pu participer au combat."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "EP5_ACT3_STAGE4_END@106#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 106
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 185
L6_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L7_1 = "쓰러진 원인이...... 어이없게도 과로로 인한 몸살이었거든."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "倒れた原因が……呆れることに、過労による体調不良だったのよね。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "I passed out before the test from all the stress and overwork."
L6_1.m_Talk_ENG = L7_1
L7_1 = "我倒下的原因……毫不意外的，是過勞引起的身體疼痛。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ฉันหมดสติไประหว่างการสอบ เพราะความเครียดและการทำงานหนักเกินไป"
L6_1.m_Talk_THA = L7_1
L7_1 = "Tôi đã bất tỉnh trước kỳ thi vì căng thẳng và làm việc quá sức."
L6_1.m_Talk_VTN = L7_1
L7_1 = "无语的是，最后倒下是因为……过劳引起的浑身酸痛。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Ich war vor der Prüfung vor lauter Stress und Überarbeitung ohnmächtig geworden."
L6_1.m_Talk_DEU = L7_1
L7_1 = "À cause du stress et du surmenage, je me suis évanouie avant le test."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
