L12_1 = "EP5_ACT3_STAGE4_END@111#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 111
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 185
L11_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L12_1 = "그때 선별 감독관...... 리플레이서 퀸이 내게 다가와서 말하더라고......"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "その時、選別監督官……リプレイサー・クイーンが私に近づいてこう言ったの。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Then the overseer, Replacer Queen, came up to me and said"
L11_1.m_Talk_ENG = L12_1
L12_1 = "那個時候選拔督察員……克隆．女皇走過來對我說……"
L11_1.m_Talk_TWN = L12_1
L12_1 = "จากนั้นผู้คุมสอบ รีเพลสเซอร์ ควีนก็มาหาฉัน แล้วบอกว่า"
L11_1.m_Talk_THA = L12_1
L12_1 = "Sau đó, người giám thị, Quân Hậu Nhân Bản, đã đến với tôi và nói"
L11_1.m_Talk_VTN = L12_1
L12_1 = "那个时候筛选督察员……克隆·女皇走过来和我说……"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Dann kam die Aufseherin, Replacer-Queen, zu mir."
L11_1.m_Talk_DEU = L12_1
L12_1 = "C'est à ce moment-là que la surveillante, la reine des substituts, est venue me voir et m'a dit"
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "EP5_ACT3_STAGE4_END@112#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 112
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 185
L12_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L13_1 = "그렇게 마음만 급해서 자기자신을 채찍질 해봐야 바뀌는 건 아무것도 없다고."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "そんなに焦って自分を追い込んだって、何も変わりやしない。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "that I wouldn't be able to get anything by pushing myself too hard without a purpose."
L12_1.m_Talk_ENG = L13_1
L13_1 = "只是因為心急而鞭策自己的話，什麼都不會改變的。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ฉันจะไม่มีทางได้อะไรจากการกดดันตัวเองมากเกินไปโดยไร้จุดหมาย"
L12_1.m_Talk_THA = L13_1
L13_1 = "rằng tôi sẽ không thể đạt được bất cứ thứ gì nếu cố gắng quá sức mà không có mục đích."
L12_1.m_Talk_VTN = L13_1
L13_1 = "只是如此心急地鞭策自己的话，什么都不会改变的。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Sie sagte, dass ich nichts erreichen würde, wenn ich mich ziellos überanstrenge."
L12_1.m_Talk_DEU = L13_1
L13_1 = "que je n'arriverais jamais à rien si je me démenais sans avoir de but précis."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "EP5_ACT3_STAGE4_END@113#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 113
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 185
L13_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L14_1 = "정말 인정 받고 싶다면 감독관인 자신이 아니라, 주위를 돌아보고 동료에게 인정받기 위해 노력하라고......"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "本当に認められたいなら、監督官である自分じゃなくて、\nまず周りの仲間に認められるために努力しなさいと。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "She said that I would need to try and earn faith and respect from my colleagues rather than trying to impress the overseer."
L13_1.m_Talk_ENG = L14_1
L14_1 = "真的想獲得認可的話，不是身為監察官的她，而是去環顧周圍，為了得到夥伴的認可而努力。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "เธอบอกว่าฉันต้องพยายามทำให้เพื่อนๆ ศรัทธาและเคารพฉัน แทนที่จะพยายามทำให้ผู้คุมสอบประทับใจ"
L13_1.m_Talk_THA = L14_1
L14_1 = "Cô ấy nói rằng tôi cần cố gắng tạo ra niềm tin và sự tôn trọng từ đồng nghiệp hơn là cố gắng gây ấn tượng với người giám thị."
L13_1.m_Talk_VTN = L14_1
L14_1 = "真的想得到认可的话，不是要得到作为监察官的她的认可；而是要去环顾周围，为了真心得到同伴的认可而努力。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Sie sagte, ich solle versuchen, das Vertrauen und den Respekt meiner Kameraden zu verdienen, anstatt die Aufseherin beeindrucken zu wollen."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Elle m'a dit que je devais essayer de gagner la confiance et le respect de mes collègues plutôt que de vouloir impressionner la surveillante."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "EP5_ACT3_STAGE4_END@114#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 114
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 185
L14_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L15_1 = "하하, 국제적 테러리스트가 하는 말 치고는 너무 정론이라서 지금도 어이가 없다니까?"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "はは、国際的なテロリストの発言にしてはあまりにも正論過ぎて、今でもわけがわからないよ。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Can you believe that came from an internationally notorious terrorist?"
L14_1.m_Talk_ENG = L15_1
L15_1 = "哈哈，國際恐怖分子說的話太有道理了，我到現在都還覺得很沒面子呢！"
L14_1.m_Talk_TWN = L15_1
L15_1 = "เชื่อไหมว่านั่นออกจากปากของผู้ก่อการร้ายที่มีชื่อฉาวโฉ่ระดับโลก?"
L14_1.m_Talk_THA = L15_1
L15_1 = "Bạn có thể tin rằng điều đó được nói ra từ một tên khủng bố khét tiếng quốc tế không?"
L14_1.m_Talk_VTN = L15_1
L15_1 = "哈哈，身为国际恐怖分子说的话太有道理了，我到现在都还觉得很无语呢！"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Ganz schön einfühlsam für eine international berüchtigte Terroristin, oder?"
L14_1.m_Talk_DEU = L15_1
L15_1 = "Difficile de croire que ça vienne d'une terroriste de renommée internationale, pas vrai ?"
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
