L22_1 = "그래. 그때 네게 말했던 아는 언니 이야기야."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "そう、あの時、あなたに話した知り合いのお姉ちゃんの話だよ。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Yes. I was talking about Queen back then."
L21_1.m_Talk_ENG = L22_1
L22_1 = "沒錯。就是跟妳說過的那個認識的姐姐。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "ใช่ ตอนนั้นฉันพูดถึงควีน"
L21_1.m_Talk_THA = L22_1
L22_1 = "Đúng. Tôi đã nói về Quân Hậu hồi đó."
L21_1.m_Talk_VTN = L22_1
L22_1 = "没错。就是以前跟你说过的那个认识的姐姐。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Ja, ich meinte damals Queen."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Oui. Je parlais de la reine."
