L22_1.m_Talk_ENG = L23_1
L23_1 = "和、和那個時候感覺完全不一樣啊！"
L22_1.m_Talk_TWN = L23_1
L23_1 = "สะ-สองเรื่องนี้ฟังดูไม่น่าจะอยู่ในหมวดเดียวกันได้เลยนะ!"
L22_1.m_Talk_THA = L23_1
L23_1 = "H-hai câu chuyện đó thậm chí không giống như chúng thuộc cùng một kiểu!"
L22_1.m_Talk_VTN = L23_1
L23_1 = "和，和那个时候感觉完全不一样啊！"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Die beiden Geschichten klingen nicht mal so, als gehörten sie zum selben Genre!"
L22_1.m_Talk_DEU = L23_1
L23_1 = "C-Ces deux histoires ne font clairement pas partie du même genre !"
