L27_1 = "그리운 사람 이야기라며?!"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "恋しい人の話じゃなかったの！？"
L26_1.m_Talk_JPN = L27_1
L27_1 = "You said it was about someone you missed!"
L26_1.m_Talk_ENG = L27_1
L27_1 = "不是說妳的思念之人嗎？！"
L26_1.m_Talk_TWN = L27_1
L27_1 = "เธอบอกว่าเรื่องนั้นเกี่ยวกับใครอีกคนหนึ่งที่เธอคิดถึง!"
L26_1.m_Talk_THA = L27_1
L27_1 = "Bạn đã nói câu chuyện đó là về một người mà bạn đã bỏ lỡ!"
L26_1.m_Talk_VTN = L27_1
L27_1 = "不是说是你思念的人？！"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Es klang damals so, als würdest du die Person vermissen!"
L26_1.m_Talk_DEU = L27_1
L27_1 = "Tu parlais d'une personne qui te manquait !"
