L27_1.m_Pos = "L"
L28_1 = "그 이야기의 어디가 그리운 사람에 대한 이야기야?!"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "これのどこが、恋しい人の話なのよ！？"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Exactly which part of this story suggests that Queen's the one you missed?"
L27_1.m_Talk_ENG = L28_1
L28_1 = "這哪裡是妳思念之人的事情了？！"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ส่วนไหนในเรื่องที่บ่งชึ้ว่าควีนคือคนที่เธอคิดถึงกันแน่?"
L27_1.m_Talk_THA = L28_1
L28_1 = "Chính xác thì phần nào của câu chuyện này cho thấy rằng Quân Hậu là người bạn đã bỏ lỡ?"
L27_1.m_Talk_VTN = L28_1
L28_1 = "这哪里和思念的人有关了？！"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Jetzt habe ich nicht den Eindruck, als würdest du Queen vermissen …"
L27_1.m_Talk_DEU = L28_1
L28_1 = "C'est quelle partie de ta petite histoire qui suggère que c'est la reine qui te manquait ?"
L27_1.m_Talk_FRA = L28_1
