L28_1.m_Face = "UNIT_LAUGH"
L28_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L28_1.m_Pos = "R"
L29_1 = "왜 그래? 내가 퀸을 얼마나 그리워했는데?"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "なに言ってるの？　私がどれだけクイーンのことを想っていたか。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Huh? Do you know how much I wanted to meet Queen again?"
L28_1.m_Talk_ENG = L29_1
L29_1 = "怎麼了？我很想女皇啊？"
L28_1.m_Talk_TWN = L29_1
L29_1 = "หืม? เธอรู้ไหมว่าฉันอยากพบควีนอีกครั้งมากแค่ไหน?"
L28_1.m_Talk_THA = L29_1
L29_1 = "Hử? Bạn có biết tôi đã muốn gặp lại Quân Hậu đến mức nào không?"
L28_1.m_Talk_VTN = L29_1
L29_1 = "怎么了？我多么想女皇啊？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Hm? Hast du eine Ahnung …"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Hein ? Tu te rends pas compte à quel point je voulais revoir la reine ?"
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "EP5_ACT3_STAGE4_END@129#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 129
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 185
L29_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L29_1.m_Pos = "R"
L30_1 = "반드시 다시 만나서 그 빌어먹을 여자를 후회하게 만들어 주겠다고 몇 번이나 다짐했거든."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "必ずや再会して、あの女を後悔させてやるって何度も胸に誓ったわ。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "I was determined to face that damned wench again and make her beg for forgiveness!"
L29_1.m_Talk_ENG = L30_1
L30_1 = "我一定會回來見她，讓那個該死的女人後悔，這些我提醒自己無數次了。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ฉันตั้งใจที่จะเผชิญหน้ากับนังตัวแสบนั่นอีกครั้ง แล้วก็ทำให้มันอ้อนวอนขอความเมตตา!"
L29_1.m_Talk_THA = L30_1
L30_1 = "Tôi đã quyết tâm đối mặt với người đàn bà chết tiệt đó một lần nữa và bắt cô ấy cầu xin sự tha thứ!"
L29_1.m_Talk_VTN = L30_1
L30_1 = "我一定要再见到她，让那个该死的女人后悔。我都已经下定决心很多次了。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Ich bin entschlossen, dieser miesen Schlampe noch einmal gegenüberzutreten und sie um Vergebung winseln zu lassen!"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Je voulais vraiment faire face à cette maudite sorcière et lui faire implorer mon pardon !"
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
