L30_1.m_Pos = "R"
L31_1 = "직접 싸워서 이길 수는 없겠지만......"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "直接対決で勝つことはできなくても……"
L30_1.m_Talk_JPN = L31_1
L31_1 = "I won't be able to take her down myself,"
L30_1.m_Talk_ENG = L31_1
L31_1 = "雖然直接戰鬥沒辦法贏過她……"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ฉันคงโค่นควีนด้วยตัวคนเดียวไม่ได้"
L30_1.m_Talk_THA = L31_1
L31_1 = "Tôi sẽ không thể tự mình hạ gục cô ta,"
L30_1.m_Talk_VTN = L31_1
L31_1 = "虽然直接战斗没办法赢过她……"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Ich werde nicht in der Lage sein, sie selbst zu Fall zu bringen."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Je sais que je ne peux pas la faire tomber moi-même,"
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "EP5_ACT3_STAGE4_END@131#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 131
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 185
L31_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L31_1.m_Pos = "R"
L32_1 = "적어도 그 여자의 진짜 목표가 뭐든 절대 이루어지지 않도록 죽을 힘을 다해서 방해하고, 또 방해해 주겠다고."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "彼女の真の目的が何であれ、決して達成はさせまいと、死ぬ気で絶対に阻止してやるんだと。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "but I'll at least be the biggest hassle in her life, the biggest pain in her neck, to keep her from achieving whatever it is that she's trying to do."
L31_1.m_Talk_ENG = L32_1
L32_1 = "但至少也要讓那個女人的真正目的無法實現，拚死也要阻止她，阻止這一切。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "แต่อย่างน้อยฉันก็จะเป็นอุปสรรคที่ใหญ่ที่สุดในชีวิตของเขา เป็นสิ่งที่กวนใจเขาที่สุด และเป็นสิ่งที่จะขัดขวางไม่ให้เขาบรรลุสิ่งที่ต้องการ ไม่ว่าจะเป็นอะไรก็ตาม"
L31_1.m_Talk_THA = L32_1
L32_1 = "nhưng ít nhất tôi sẽ là rắc rối lớn nhất trong cuộc đời cô ta, nỗi đau lớn nhất, khiến cô ta không thể đạt được bất cứ điều gì cô ta đang cố gắng làm."
L31_1.m_Talk_VTN = L32_1
L32_1 = "但至少也要用尽全力妨碍她，让她的真正目标无法实现，不管那个目的是什么。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Aber ich werde das größte Ärgernis in ihrem Leben sein, der größte Plagegeist, der sie davon abhält, ihre Ziele zu erreichen."
L31_1.m_Talk_DEU = L32_1
L32_1 = "mais au moins je peux être son plus gros problème, sa plus vive douleur, celle qui l'empêchera de réaliser ce qu'elle a entrepris."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
