L33_1.m_Pos = "L"
L34_1 = "둘이 사이 좋았던 거 아니었어?"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "二人は仲良しって流れじゃなかったの？"
L33_1.m_Talk_JPN = L34_1
L34_1 = "It sounded like you liked her back then."
L33_1.m_Talk_ENG = L34_1
L34_1 = "你們兩個的關係不是很好嗎？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ฟังดูเหมือนแต่ก่อนเธอก็ชอบเขานะ"
L33_1.m_Talk_THA = L34_1
L34_1 = "Nghe có vẻ như bạn thích cô ấy hồi đó."
L33_1.m_Talk_VTN = L34_1
L34_1 = "你们俩不是关系很好吗？"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Es klang irgendwie so, als ob du sie damals gemocht hättest."
L33_1.m_Talk_DEU = L34_1
L34_1 = "J'avais l'impression que tu l'aimais à l'époque."
L33_1.m_Talk_FRA = L34_1
