L36_1 = "패배한 팀원들을 추슬러서 간신히 와일드카드를 얻어내고......"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "あの後、敗北したチームメンバーをなんとか取りまとめて、やっとの思いでワイルドカードを獲得した。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "At least until I picked up my teammates from despair, managed to win a wild card,"
L35_1.m_Talk_ENG = L36_1
L36_1 = "當我們失敗的隊員重新振作，好不容易獲得了參賽名額……"
L35_1.m_Talk_TWN = L36_1
L36_1 = "อย่างน้อยก็จนกระทั่งฉันช่วยสมาชิกในทีมที่สิ้นหวัง ชนะการต่อสู้"
L35_1.m_Talk_THA = L36_1
L36_1 = "Ít nhất là cho đến khi tôi đưa đồng đội của mình thoát khỏi tuyệt vọng, giành được thẻ hoang dã,"
L35_1.m_Talk_VTN = L36_1
L36_1 = "我好不容易劝说失败的队员重新振作，并获得了参赛名额……"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Zumindest so lange, bis ich meine Teamkameraden aus ihrer Verzweiflung holen, einen Joker ziehen"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Jusqu'à ce que je parvienne à remotiver mes coéquipiers, obtienne une nouvelle invitation,"
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
