L36_1.m_Pos = "R"
L37_1 = "압도적인 전력 차의 우승팀과 재대결에서 승리한 다음......"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "そして、圧倒的に強かった優勝チームとの再対決で勝利を収めたけど……"
L36_1.m_Talk_JPN = L37_1
L37_1 = "won at the rematch against the formidable champions,"
L36_1.m_Talk_ENG = L37_1
L37_1 = "並和戰力有壓倒性差距的隊伍再度對決，取得勝利之後……"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ชนะศึกเล่นซ้ำกับแชมป์ที่น่าเกรงขาม"
L36_1.m_Talk_THA = L37_1
L37_1 = "chiến thắng trong trận tái đấu với những nhà vô địch đáng gờm,"
L36_1.m_Talk_VTN = L37_1
L37_1 = "在和有压倒性战斗力优势的队伍再次对决后终于胜利了……"
L36_1.m_Talk_SCN = L37_1
L37_1 = "und den Rückkampf gegen die Champions gewinnen konnte."
L36_1.m_Talk_DEU = L37_1
L37_1 = "gagne ma revanche contre les plus grands champions,"
L36_1.m_Talk_FRA = L37_1
