L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L37_1.m_Pos = "R"
L38_1 = "기쁜 얼굴로 달려간 나와 팀원들을 모조리 인자 추출기 안에 집어넣기 전까지는 말이야."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "歓喜の顔で駆け付けた私やチームメンバー全員は、ファクター抽出器に放り込まれたのよ。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "only to be shoved inside a Factor Extractor along with the rest of my teammates!"
L37_1.m_Talk_ENG = L38_1
L38_1 = "我和隊員們全都高興地跑向她，接著我們卻全被抓進了因子萃取器裡……"
L37_1.m_Talk_TWN = L38_1
L38_1 = "แต่กลับถูกจับส่งเข้าเครื่องสกัดแฟกเตอร์พร้อมๆ กับสมาชิกในทีมคนอื่นๆ นั่นละ!"
L37_1.m_Talk_THA = L38_1
L38_1 = "chỉ để được đẩy vào bên trong Bộ Trích Xuất Nhân Tố cùng với các đồng đội còn lại của tôi!"
L37_1.m_Talk_VTN = L38_1
L38_1 = "但是在我和队员们高兴的跑向她的时候，却都被抓进了因子萃取器。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Aber dann wurde ich zusammen mit meinen Teamkameraden in einen Faktor-Extraktor gesteckt!"
L37_1.m_Talk_DEU = L38_1
L38_1 = "pour au final être balancée dans un extracteur d'agent avec le reste de mes coéquipiers !"
L37_1.m_Talk_FRA = L38_1
