L40_1 = "나중에 알게 된 사실이지만 난 선별되지 못한 게 아니었어."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "後から知ったけど、私は選別テストに落ちたわけじゃなかった。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "I found out later, but I was left there for a reason."
L39_1.m_Talk_ENG = L40_1
L40_1 = "雖然我之後才知道，我不是沒被選中。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ฉันมารู้ที่หลังนะว่าฉันถูกทิ้งไว้ที่นั่นด้วยเหตุผลบางอย่าง"
L39_1.m_Talk_THA = L40_1
L40_1 = "Sau đó tôi đã phát hiện ra, nhưng tôi bị bỏ lại ở đó là có lý do."
L39_1.m_Talk_VTN = L40_1
L40_1 = "我之后才知道，我不是没被选中。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Wie ich später herausfand, landete ich aus einem bestimmten Grund dort."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Je ne l'ai su qu'après, mais on m'a laissée là pour une raison précise."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "EP5_ACT3_STAGE4_END@140#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 140
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 185
L40_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L40_1.m_Pos = "R"
L41_1 = "나와 함께 최종 테스트까지 도달한 아이들은 모두 얼터너티브 인자 이식용 실험체로 결정되어 있었던 거야."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "私と一緒に最終テストまでたどり着いたメンバーは、\n全員がオルタナティブ・ファクター移植用の実験体になることが決まってたのよ。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "All the kids who made it to the end of the test were destined to be used as subjects in the Alternative Factor transplant experiments."
L40_1.m_Talk_ENG = L41_1
L41_1 = "而是和我一起通過最終測試的孩子們，全都被選為移植用的可替代因子試驗體。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "เด็กทุกคนที่รอดมาจนจบการทดสอบจะถูกนำไปใช้เป็นตัวทดลอง\nในการทดลองปลูกถ่ายอัลเทอร์เนทีฟแฟกเตอร์"
L40_1.m_Talk_THA = L41_1
L41_1 = "Tất cả những đứa trẻ vượt qua được bài kiểm tra đều được sử dụng làm đối tượng trong các thí nghiệm cấy ghép Nhân Tố Nhân Bản."
L40_1.m_Talk_VTN = L41_1
L41_1 = "而是我和那些进入最终测试的孩子们都被选为了用于可替代因子移植的试验体。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Alle Kinder, die es bis zum Ende des Tests schafften, waren dazu bestimmt, in Experimenten zur Transplantation des Alternativ-Faktors als Testsubjekte verwendet zu werden."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Tous les enfants qui parvenaient à aller jusqu'au bout des tests étaient destinés à devenir des cobayes pour les expériences de transplantation de l'agent alternatif."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
