L41_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L41_1.m_Pos = "L"
L42_1 = "그럼...... 어째서 너에게 그런 조언을 한 거야?"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "だったら、なぜあんたにあんな助言をしたんだろう？"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Then why did she give you that advice?"
L41_1.m_Talk_ENG = L42_1
L42_1 = "那……她為什麼要給妳那個建議？？"
L41_1.m_Talk_TWN = L42_1
L42_1 = "งั้นควีนจะให้คำแนะนำกับเธอแบบนั้นทำไม?"
L41_1.m_Talk_THA = L42_1
L42_1 = "Vậy tại sao cô ta lại cho bạn lời khuyên đó?"
L41_1.m_Talk_VTN = L42_1
L42_1 = "那……为什么要对你说那样的话呢？"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Warum hatte sie dir dann den einfühlsamen Rat gegeben?"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Mais alors pourquoi elle t'a donné ce conseil ?"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "EP5_ACT3_STAGE4_END@142#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 142
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 185
L42_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "UNIT_IDLE"
L42_1.m_Face = L43_1
L42_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L42_1.m_Pos = "R"
L43_1 = "글쎄? 아마도 승부에 대한 집착이나 동료애 같은 정신적 요소가 실험 데이터에 필요했나 보지."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "さあ？　わからないけど、勝負への執念や仲間想いのようなメンタル要素が実験データに必要だったのかもね。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Who knows? Maybe she wanted to find out how mental factors like desire to win or comradeship affected performance for her research."
L42_1.m_Talk_ENG = L43_1
L43_1 = "誰知道呢，大概實驗資料需要對勝利的執著，和夥伴情誼這些精神要素吧。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ใครจะไปรู้ล่ะ? เธออาจจะแค่อย่างดูว่าปัจจัยทางความคิด เช่น ความปรารถนาที่จะชนะหรือมิตรภาพจะส่งผลต่อการทำงานของงานวิจัยเธอหรือไม่"
L42_1.m_Talk_THA = L43_1
L43_1 = "Ai mà biết? Có lẽ cô ta muốn tìm hiểu xem các nhân tố tinh thần như khát khao chiến thắng hay tình đồng đội đã ảnh hưởng như thế nào đến hiệu suất trong nghiên cứu của cô ta."
L42_1.m_Talk_VTN = L43_1
L43_1 = "谁知道呢，说不定是实验数据需要对胜利的执着和竞争者友谊这种精神要素呢。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Wer weiß? Vielleicht wollte sie für ihre Forschung herausfinden, ob mentale Faktoren, wie Siegeswillen oder Kameradschaft, die Leistung beeinflussen."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Va savoir. Elle voulait peut-être observer les effets de l'espoir et de l'esprit de compétition sur ses expériences."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "EP5_ACT3_STAGE4_END@143#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 143
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 185
L43_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L43_1.m_Pos = "R"
L44_1 = "그게 아니면 한치 앞도 못 보는 멍청이가 손바닥 위에서 춤을 추는 게 재미있었을 수도 있고."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "それとも、目前の危機にも気が付かないマヌケが、手のひらの上で躍らされるのが楽しかったのかも。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Or, she was just having fun watching an idiot making a fool of herself."
L43_1.m_Talk_ENG = L44_1
L44_1 = "要不然就是喜歡把我們玩弄在股掌之間的感覺。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "หรือเธออาจจะแค่สนุกกับการได้เห็นคนโง่ทำตัวโง่ๆ ก็ได้"
L43_1.m_Talk_THA = L44_1
L44_1 = "Hoặc, cô ta chỉ đang vui vẻ khi nhìn một tên ngốc diễn trò."
L43_1.m_Talk_VTN = L44_1
L44_1 = "要不然就是喜欢把我们玩弄在股掌之间的感觉呢。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Oder sie hatte einfach Spaß daran, mir zuzuschauen, wie ich mich noch mehr zum Narren machte."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Ou alors, elle aimait juste regarder une idiote se ridiculiser."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "EP5_ACT3_STAGE4_END@144#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 144
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 185
L44_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L44_1.m_Pos = "R"
L45_1 = "뭐가 됐건 우리에게 그런 걸 고민할 틈 따윈 없었어."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "どっちにしろ、私たちにそんなことを考えてる暇はなかった。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Whatever it was, we didn't have the luxury to think."
L44_1.m_Talk_ENG = L45_1
L45_1 = "不管怎樣，我們都沒有空去管那些事。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "จะอะไรก็ช่าง เราไม่มีสิทธิ์ที่จะคิด"
L44_1.m_Talk_THA = L45_1
L45_1 = "Dù đó là gì, suy nghĩ về nó là điều xa xỉ với chúng tôi."
L44_1.m_Talk_VTN = L45_1
L45_1 = "不过对于我们来说也没时间思考那些。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Aber ich hatte nicht die Muße, darüber nachzudenken."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Quelles qu'étaient ses motivations, on a pas eu le temps d'y réfléchir."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "EP5_ACT3_STAGE4_END@145#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 145
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 185
L45_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L45_1.m_Pos = "R"
L46_1 = "그날부터 바로 하루에 10시간이 넘게 추출기에 들어가 있으면서 온몸이 새로 만들어지는 고통을 겪어야 했거든."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "その日から、一日10時間以上、抽出器のなかで全身が\n作り変えられるような苦しみに耐えなければならなかったからね。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Since that very day, we had to spend over 10 hours a day in an Extractor, suffering pain from physical reconstruction."
L45_1.m_Talk_ENG = L46_1
L46_1 = "那之後的每一天，我們都在因子萃取器裡待10小時以上，體會身體重新被塑造的痛苦。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "นับแต่วันนั้นเป็นต้นมา เราต้องใช้เวลาในเครื่องสกัดมากกว่าวันละสิบชั่วโมง ต้อนทนเจ็บปวดจากการปรับโครงสร้างร่างกายใหม่"
L45_1.m_Talk_THA = L46_1
L46_1 = "Kể từ ngày hôm đó, chúng tôi phải dành hơn 10 giờ mỗi ngày trong một Bộ Trích Xuất, chịu đựng những cơn đau do tái tạo thể chất."
L45_1.m_Talk_VTN = L46_1
L46_1 = "那之后的每天都要在因子萃取器里呆超过10个小时，体会身体被重新塑造的痛苦。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Von diesem Tag an verbrachten wir mehr als 10 Stunden täglich in einem Extraktor und litten unter den Schmerzen der physischen Rekonstruierung."
L45_1.m_Talk_DEU = L46_1
L46_1 = "À partir de ce jour, on a passé plus de 10 heures par jour dans un extracteur, à endurer les souffrances de la reconstruction physique."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "EP5_ACT3_STAGE4_END@146#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 146
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 185
L46_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L46_1.m_Pos = "R"
L47_1 = "그 와중에 겪어야 하는 39도가 넘는 고열이나 각종 조직 괴사 같은 부작용은 덤이고."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "おまけに、39度以上の高熱や様々な体内組織が壊死するような副作用もついてきた。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Our fever spiked over 39 degrees Celsius, and our skin tissues started to die."
L46_1.m_Talk_ENG = L47_1
L47_1 = "在這個過程中，還附帶超過39度的高溫和各種組織壞死的副作用。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "เรามีไข้พุ่งสูงเกิน 39 องศาเซลเซียส เนื้อเยื่อผิวหนังของเราเริ่มตาย"
L46_1.m_Talk_THA = L47_1
L47_1 = "Cơn sốt của chúng tôi tăng vọt hơn 39 độ C, và các mô da của chúng tôi bắt đầu chết."
L46_1.m_Talk_VTN = L47_1
L47_1 = "还要经历超过39度的高温和各种组织坏死的副作用。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Unser Fieber stieg auf über 39 Grad Celsius, und unser Hautgewebe begann abzusterben."
L46_1.m_Talk_DEU = L47_1
L47_1 = "On faisait des poussées de fièvres à plus de 39, et les tissus de notre peau ont commencé à se nécroser."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
