L49_1 = "EP5_ACT3_STAGE4_END@148#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 148
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 185
L48_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L48_1.m_Pos = "R"
L49_1 = "1차 실험이 끝났을 때, 살아남은 적성체는 우리 네 명뿐이었어."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "第1次実験が終わった後、生き残った適性体は私たち4人だけだったの。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "When the first experiment was over, us four were the only survivors."
L48_1.m_Talk_ENG = L49_1
L49_1 = "第一次實驗結束後，活下來的適性體就我們四個人。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ตอนที่การทดลองสิ้นสุดลง เหลือผู้รอดชีวิตแค่สี่คนเท่านั้น"
L48_1.m_Talk_THA = L49_1
L49_1 = "Khi thí nghiệm đầu tiên kết thúc, bốn người chúng tôi là những người sống sót duy nhất."
L48_1.m_Talk_VTN = L49_1
L49_1 = "第一次实验结束后，活下来的适应体就我们四个人。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Als das erste Experiment beendet war, waren wir vier die einzigen Überlebenden."
L48_1.m_Talk_DEU = L49_1
L49_1 = "À la fin de la première expérience, nous n'étions plus que quatre survivantes."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "EP5_ACT3_STAGE4_END@149#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 149
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 185
L49_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L49_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L49_1.m_Pos = "L"
L50_1 = "그래서 도망친 거야?"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "それで、逃げ出したの？"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Was that when you ran away?"
L49_1.m_Talk_ENG = L50_1
L50_1 = "所以你們就逃跑了？"
L49_1.m_Talk_TWN = L50_1
L50_1 = "แล้วตอนไหนที่เธอหนีออกมา?"
L49_1.m_Talk_THA = L50_1
L50_1 = "Đó có phải là lúc bạn chạy trốn không?"
L49_1.m_Talk_VTN = L50_1
L50_1 = "然后你们逃跑了吗？"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Und dann konntest du entkommen?"
L49_1.m_Talk_DEU = L50_1
L50_1 = "C'est là que vous vous êtes enfuies ?"
L49_1.m_Talk_FRA = L50_1
