L3_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L4_1 = "다행히 그때쯤 리플레이서 내부에서 작은 반란 사건이 벌어졌었어."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "幸いなことに、その頃リプレイサーの中で小さな反乱が起こったの。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Fortunately, there was a small-scale revolt inside the Syndicate."
L3_1.m_Talk_ENG = L4_1
L4_1 = "幸運的是，那個時候克隆集團內部發生了小叛亂。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "โชคดีที่ตอนนั้นเกิดการลุกฮือย่อมๆ ขึ้นในซินดิเคต"
L3_1.m_Talk_THA = L4_1
L4_1 = "May mắn thay, có một cuộc nổi dậy quy mô nhỏ trong nội bộ Nghiệp Đoàn."
L3_1.m_Talk_VTN = L4_1
L4_1 = "幸运的是，那个时候克隆集团内部发生了小叛乱。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Glücklicherweise kam es innerhalb des Syndikats zu einer kleinen Revolte."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Heureusement, il y a eu une petite révolte au sein du Syndicat."
L3_1.m_Talk_FRA = L4_1
