L19_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L20_1 = "자세한 건 모르지만 이안...... 뭐라고 하는 시니어 연구원이 고위 침식체를 연구소 내부에 풀어놓은 것 같던데......"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "詳しいことはわからないけど、イアン……なんとかというシニア研究員が、\n高位侵食体を研究所の中に解放したらしい……"
L19_1.m_Talk_JPN = L20_1
L20_1 = "I don't remember all the details, but this senior researcher named Ian something released a high-category C.O. inside the lab."
L19_1.m_Talk_ENG = L20_1
L20_1 = "具體的我也不清楚，叫伊恩……什麼的資深研究員好像把高等侵蝕體放到研究院內部……"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ฉันจำรายละเอียดทั้งหมดไม่ได้นะ แต่มีนักวิจัยอาวุโสที่ชื่อเอียนหรืออะไรสักอย่าง เขาปล่อยวัตถุคอร์รัปต์คลาสสูงเข้าไปในห้องแล็บ"
L19_1.m_Talk_THA = L20_1
L20_1 = "Tôi không nhớ tất cả các chi tiết, nhưng nhà nghiên cứu cấp cao tên Ian cái gì đó đã thả một V.T.B.A.M bên trong phòng thí nghiệm."
L19_1.m_Talk_VTN = L20_1
L20_1 = "具体的我也不清楚，但是叫伊恩……什么的高级研究员好像把高级侵蚀体放到研究院内部了……"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Ich erinnere mich nicht an alle Einzelheiten, aber ein Forscher namens Ian hatte ein hochkarätiges C. O. im Labor freigelassen."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Je me rappelle pas des détails, mais un des chercheurs principaux nommé Ian quelque chose a libéré un O.C. de catégorie supérieure dans le labo."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "EP5_ACT3_STAGE4_END@170#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 170
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 185
L20_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L21_1 = "그 틈을 타서 우리도 탈출에 성공할 수 있었지."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "その隙に、私たちは脱出できたの。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "We took advantage of it and escaped during the commotion."
L20_1.m_Talk_ENG = L21_1
L21_1 = "趁這個機會，我們才能夠成功逃脫的。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "เราฉวยโอกาสนี้หนีระหว่างที่สถานการณ์ชุลมุน"
L20_1.m_Talk_THA = L21_1
L21_1 = "Chúng tôi đã tận dụng nó và trốn thoát trong lúc hỗn loạn."
L20_1.m_Talk_VTN = L21_1
L21_1 = "趁这个机会我们才得以成功逃脱的。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Wir nutzten den Aufruhr, um uns aus dem Staub zu machen."
L20_1.m_Talk_DEU = L21_1
L21_1 = "On a profité du désordre et on s'est échappées."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "EP5_ACT3_STAGE4_END@171#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 171
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 185
L21_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L22_1 = "이안......? 혹시 이안 메이슨이라는 이름 아니었어?"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "イアン……？　もしかして、イアン・メイソンって名前じゃない？"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Ian? Was his last name Mason?"
L21_1.m_Talk_ENG = L22_1
L22_1 = "伊恩……？該不會是叫伊恩．梅森嗎？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "เอียนเหรอ? นามสกุลเมสันรึเปล่า?"
L21_1.m_Talk_THA = L22_1
L22_1 = "Ian? Họ của anh ấy có phải là Mason không?"
L21_1.m_Talk_VTN = L22_1
L22_1 = "伊恩……？伊恩·梅森吗？"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Ian? Lautete sein Nachname Mason?"
L21_1.m_Talk_DEU = L22_1
L22_1 = "Ian ? Il s'appelait Ian Mason ?"
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "EP5_ACT3_STAGE4_END@172#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 172
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 185
L22_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L23_1 = "글쎄......? 그랬던 것 같기도 하고......"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "さあ……？　そんな気もするけど……"
L22_1.m_Talk_JPN = L23_1
L23_1 = "I don't know. Maybe it was."
L22_1.m_Talk_ENG = L23_1
L23_1 = "這……？好像是……"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ไม่รู้สิ อาจใช่ก็ได้"
L22_1.m_Talk_THA = L23_1
L23_1 = "Tôi không biết. Có lẽ là vậy."
L22_1.m_Talk_VTN = L23_1
L23_1 = "难说……？好像是的……"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Keine Ahnung, kann sein …"
L22_1.m_Talk_DEU = L23_1
L23_1 = "Je sais pas. Peut-être."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "EP5_ACT3_STAGE4_END@173#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 173
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 185
L23_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L24_1 = "잘 모르겠어, 혹시 아는 사람이야?"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "よくわからない。もしかして知り合いなの？"
L23_1.m_Talk_JPN = L24_1
L24_1 = "I can't be sure. Why? Do you know him?"
L23_1.m_Talk_ENG = L24_1
L24_1 = "我也不清楚，妳該不會認識他吧？"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ฉันก็ไม่แน่ใจ ทำไม? เธอรู้จักเขาเหรอ?"
L23_1.m_Talk_THA = L24_1
L24_1 = "Tôi không thể chắc chắn. Tại sao? Bạn có biết anh ta không?"
L23_1.m_Talk_VTN = L24_1
L24_1 = "我也不清楚，你认识他吗？"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Ich bin mir nicht sicher. Warum? Kennst du ihn?"
L23_1.m_Talk_DEU = L24_1
L24_1 = "Difficile à dire. Pourquoi ? Tu le connais ?"
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "EP5_ACT3_STAGE4_END@174#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 174
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 185
L24_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L25_1 = "아, 아니야. 그 뒤엔 어떻게 됐는데?"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "い、いや、その後はどうなったの？"
L24_1.m_Talk_JPN = L25_1
L25_1 = "I-it's nothing. So what happened next?"
L24_1.m_Talk_ENG = L25_1
L25_1 = "啊，沒有。那之後怎麼樣了？"
L24_1.m_Talk_TWN = L25_1
L25_1 = "มะ-ไม่มีอะไรหรอก แล้วจากนั้นเป็นไงต่อ?"
L24_1.m_Talk_THA = L25_1
L25_1 = "K-không có gì đâu. Vậy điều gì đã xảy ra tiếp theo?"
L24_1.m_Talk_VTN = L25_1
L25_1 = "啊，不是。之后怎么样了？"
L24_1.m_Talk_SCN = L25_1
L25_1 = "N-nicht direkt … Was geschah dann?"
L24_1.m_Talk_DEU = L25_1
L25_1 = "L-Laisse tomber. Qu'est-ce qui s'est passé après ?"
L24_1.m_Talk_FRA = L25_1
