L29_1 = "EP5_ACT3_STAGE4_END@178#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 178
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 185
L28_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L29_1 = "탈출하고 나서, 한동안은 추적당할까 봐 거지꼴로 숨어 살았지."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "脱出直後しばらくの間は、追跡を警戒して、ホームレス同然の逃亡生活をしてたわ。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "After we escaped, we lived in hiding for some time."
L28_1.m_Talk_ENG = L29_1
L29_1 = "逃出來之後，我們因為害怕被追捕，有很長一段時間都假扮成乞丐躲躲藏藏。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "หลังจากที่เราหนีออกมา เราก็ซ่อนตัวอยู่สักพัก"
L28_1.m_Talk_THA = L29_1
L29_1 = "Sau khi chúng tôi trốn thoát, chúng tôi ở ẩn một thời gian."
L28_1.m_Talk_VTN = L29_1
L29_1 = "逃出来之后的好长一段时间，因为怕被追击就一直假扮乞丐东躲西藏。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Nachdem wir geflohen waren, versteckten wir uns eine Weile."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Après notre évasion, on s'est cachées pendant un moment."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
