L31_1 = "EP5_ACT3_STAGE4_END@180#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 180
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 185
L30_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L31_1 = "하지만 그런 식으로는 희망이 없다는 걸 깨달았어."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "でも、そのままじゃ望みがないことに気づいたの。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "But it didn't take long before we realized it was meaningless."
L30_1.m_Talk_ENG = L31_1
L31_1 = "但是，我們察覺到那樣是沒有希望的。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "แต่ไม่นานเราก็ตระหนักได้ว่ามันไร้ความหมาย"
L30_1.m_Talk_THA = L31_1
L31_1 = "Nhưng rất nhanh sau đó, chúng tôi nhận ra điều này thật vô nghĩa."
L30_1.m_Talk_VTN = L31_1
L31_1 = "后来才明白那样是没有希望的。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Aber wir merkten bald, dass es sinnlos war."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Mais on s'est vite rendu compte que ça ne servait à rien."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
