L33_1 = "EP5_ACT3_STAGE4_END@182#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 182
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 185
L32_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L33_1 = "언젠가는...... 리플레이서가 우릴 찾아낼 테니까."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "いずれは……リプレイサーが私たちを見つけるだろうから。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "It was only a matter of time before the Syndicate found us."
L32_1.m_Talk_ENG = L33_1
L33_1 = "因為總有一天……克隆集團會找到我們的。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ไม่นานซินดิเคตก็จะหาตัวเราเจอ"
L32_1.m_Talk_THA = L33_1
L33_1 = "Syndicate tìm thấy chúng tôi chỉ là vấn đề thời gian thôi."
L32_1.m_Talk_VTN = L33_1
L33_1 = "不知道什么时候……就会被克隆集团找到。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Es war nur eine Frage der Zeit, bis das Syndikat uns finden würde."
L32_1.m_Talk_DEU = L33_1
L33_1 = "C'était juste une question de temps avant que le Syndicat nous trouve."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "EP5_ACT3_STAGE4_END@183#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 183
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 185
L33_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L34_1 = "그래서 살아남기 위해, 힘을 기르기 위해,"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "だから、生き残る力をつけるために、"
L33_1.m_Talk_JPN = L34_1
L34_1 = "So we started our mercenary business from scratch."
L33_1.m_Talk_ENG = L34_1
L34_1 = "所以，為了活下來，為了積蓄力量……"
L33_1.m_Talk_TWN = L34_1
L34_1 = "เราเลยเริ่มทำธุรกิจทหารรับจ้างขึ้นจากศูนย์"
L33_1.m_Talk_THA = L34_1
L34_1 = "Vì vậy, chúng tôi bắt đầu công việc lính đánh thuê của mình từ đầu."
L33_1.m_Talk_VTN = L34_1
L34_1 = "所以，为了活下来，为了积蓄力量，"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Also etablierten wir uns im Söldnergeschäft von Grund auf neu."
L33_1.m_Talk_DEU = L34_1
L34_1 = "On a donc créé notre entreprise de mercenaires à partir de rien."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
