L35_1 = {}
L36_1 = "EP5_ACT3_STAGE4_END@185#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L35_1.m_CutScenProcessKey = 185
L35_1.m_CutScenID = 185
L35_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L36_1 = "간신히 팀을 만들고 밑바닥부터 용병일을 시작했어."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "なんとかチームを作って、傭兵として底辺の仕事から始めたの。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "We did it to survive—to build up strength to defend ourselves."
L35_1.m_Talk_ENG = L36_1
L36_1 = "我們艱難地創建了隊伍，從最底層開始做起了傭兵……"
L35_1.m_Talk_TWN = L36_1
L36_1 = "เราทำเพื่อเอาตัวรอด... เพื่อเสริมสร้างความแข็งแกร่งมาป้องกันตัวเราเอง"
L35_1.m_Talk_THA = L36_1
L36_1 = "Chúng tôi đã làm điều đó để tồn tại — xây dựng sức mạnh để tự vệ."
L35_1.m_Talk_VTN = L36_1
L36_1 = "艰难地组建了队伍，从最底层开始做起了佣兵……"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Wir taten es, um zu überleben – um stärker zu werden und uns zu verteidigen."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Notre survie était en jeu, on devait se renforcer pour pouvoir nous défendre."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "EP5_ACT3_STAGE4_END@186#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 186
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 185
L36_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L37_1 = "그 후에는...... 잘 알겠지?"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "そこからは……知ってのとおりよ。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "And... you know the rest."
L36_1.m_Talk_ENG = L37_1
L37_1 = "之後的事情……妳應該都知道了吧？"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ต่อจากนั้น... เธอก็รู้อยู่แล้ว"
L36_1.m_Talk_THA = L37_1
L37_1 = "Và... phần còn lại thì bạn biết rồi đó."
L36_1.m_Talk_VTN = L37_1
L37_1 = "之后的事情……你应该都知道了吧？"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Und … Na ja, den Rest der Geschichte kennst du."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Et... tu connais la suite."
L36_1.m_Talk_FRA = L37_1
