L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 191
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 185
L41_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
