L42_1 = "UNIT_IDLE"
L41_1.m_Face = L42_1
L41_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L41_1.m_Pos = "L"
L42_1 = "그래서...... 정식 라이선스를 따는 데 그렇게 집착한 건가?"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "だから……正式ライセンスにそこまでこだわってたの？"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Is that why you were so obsessed with getting the official license?"
L41_1.m_Talk_ENG = L42_1
L42_1 = "所以……為了獲得正式許可證，你們才那麼執著嗎？"
L41_1.m_Talk_TWN = L42_1
L42_1 = "เพราะแบบนี้เธอถึงหมกมุ่นกับการได้ใบอนุญาตอย่างเป็นทางการเหรอ?"
L41_1.m_Talk_THA = L42_1
L42_1 = "Đó có phải là lý do khiến bạn bị ám ảnh bởi việc nhận được giấy phép chính thức không?"
L41_1.m_Talk_VTN = L42_1
L42_1 = "所以……你很想获得正式许可证吗？"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Wart ihr deshalb so versessen darauf, eine offizielle Lizenz zu bekommen?"
L41_1.m_Talk_DEU = L42_1
L42_1 = "C'est pour ça que tu étais obnubilée par l'obtention de la licence officielle ?"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
