L42_1.m_Pos = "R"
L43_1 = "맞아. 관리국의 정식 라이선스가 있으면 생각보다 많은 지원을 받을 수 있어."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "うん。管理局の正式ライセンスがあれば、想像以上に豊富な援助を受けることができるの。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Correct. There are more benefits to being a licensed TASKFORCE team than you'd think."
L42_1.m_Talk_ENG = L43_1
L43_1 = "沒錯。有了管理局的正式許可證，就可以獲得比想像中還要多的援助。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ถูกต้อง การเป็นทีมทาสก์ฟอร์สที่มีใบอนุญาตมีสิทธิประโยชน์มากมายกว่าที่เธอคิดนะ"
L42_1.m_Talk_THA = L43_1
L43_1 = "Chính xác. Có nhiều lợi ích khi trở thành nhóm TASKFORCE được cấp phép hơn bạn nghĩ.\n"
L42_1.m_Talk_VTN = L43_1
L43_1 = "没错。有了管理局的正式许可证就可以得到很多援助。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Genau. Es bringt mehr Vorteile, ein lizenziertes TASKFORCE-Team zu sein, als man denkt."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Exact. Il y a plus d'avantages à être une escouade TASKFORCE agréée que tu le penses."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "EP5_ACT3_STAGE4_END@193#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 193
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 185
L43_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L43_1.m_Pos = "R"
L44_1 = "운이 좋으면...... 구 관리국의 고유 무장을 얻을 수도 있고."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "運が良ければ……旧管理局の固有武器も得られるし。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "If you're lucky, you could get your hands on one of the Unique Gears of the Old Administration."
L43_1.m_Talk_ENG = L44_1
L44_1 = "運氣好的話……還有可能得到舊管理局的專屬裝備。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "หากเธอโชคดี เธอก็อาจได้อุปกรณ์พิเศษขององค์การบริหารโลกในอดีตสักชิ้น"
L43_1.m_Talk_THA = L44_1
L44_1 = "Nếu may mắn, bạn có thể chạm tay vào một trong những thiết bị độc đáo của Cục Quản Lý Cũ."
L43_1.m_Talk_VTN = L44_1
L44_1 = "运气好的话……还有可能得到旧管理局的专属装备。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Mit etwas Glück kann man sogar eins der einzigartigen Ausrüstungsstücke der Alten Administration ergattern."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Avec un peu de chance, tu peux même obtenir l'une des armes uniques de l'Ancienne Administration."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "EP5_ACT3_STAGE4_END@194#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 194
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 185
L44_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L44_1.m_Pos = "R"
L45_1 = "뭐가 됐든 우릴 찾는 리플레이서 놈들을 엿 먹이는데 도움이 됐겠지."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "いずれにしても、私たちを追いかけてくるリプレイサーどもを懲らしめるのに役立つでしょうね。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "It would have helped us screwing things up for the Replacers, one way or another."
L44_1.m_Talk_ENG = L45_1
L45_1 = "不管是什麼，都能幫助我們對付克隆集團的傢伙們。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "มันจะช่วยทำให้เราเล่นงานพวกรีเพลสเซอร์ได้ ไม่ทางใดก็ทางหนึ่ง"
L44_1.m_Talk_THA = L45_1
L45_1 = "Nó sẽ giúp chúng tôi hoàn thiện mọi thứ cho Người Nhân Bản, bằng cách này hay cách khác."
L44_1.m_Talk_VTN = L45_1
L45_1 = "不管是什么都能帮助我们对付克隆集团的家伙们。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Uns interessiert alles, was hilft, den Replacern die Sache zu vermasseln."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Ça nous aurait été utile pour faire foirer les plans du Syndicat, d'une manière ou d'une autre."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
