L46_1 = "대체......"
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "いったい……"
L45_1.m_Talk_JPN = L46_1
L46_1 = "That's insane..."
L45_1.m_Talk_ENG = L46_1
L46_1 = "到底……"
L45_1.m_Talk_TWN = L46_1
L46_1 = "บ้ามาก..."
L45_1.m_Talk_THA = L46_1
L46_1 = "Thật điên rồ..."
L45_1.m_Talk_VTN = L46_1
L46_1 = "到底……"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Wahnsinn …"
L45_1.m_Talk_DEU = L46_1
L46_1 = "C'est dingue..."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "EP5_ACT3_STAGE4_END@196#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 196
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 185
L46_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L46_1.m_Pos = "L"
L47_1 = "대체 그 얼터너티브 인자인가 하는 게 뭔데 그런 끔찍한 실험을 하는 거지?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "いったい、オルタナティブ・ファクターって、何なの？　どうしてそこまで恐ろしい実験をするんだろう。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "What about the Alternative Factor is so important that they need to carry out such horrible experiments?"
L46_1.m_Talk_ENG = L47_1
L47_1 = "可替代因子到底是什麼，克隆集團竟然要做那麼殘忍的實驗？"
L46_1.m_Talk_TWN = L47_1
L47_1 = "แล้วอัลเทอร์เนทีฟแฟกเตอร์นี่มีอะไรสำคัญมากจนพวกเขาต้องทำการทดลองที่โหดร้ายแบบนั้นเหรอ?"
L46_1.m_Talk_THA = L47_1
L47_1 = "Điều gì về Nhân Tố Nhân Bản quan trọng đến mức họ cần phải thực hiện những thí nghiệm khủng khiếp như vậy?"
L46_1.m_Talk_VTN = L47_1
L47_1 = "可替代因子到底是什么啊，克隆集团竟然要做那么残忍的实验？"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Was ist an dem Alternativ-Faktor so bedeutend, dass sie solch schreckliche Experimente durchführen müssen?"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Qu'est-ce qu'il a de si important, l'agent alternatif, pour qu'ils mènent des expériences aussi horribles ?"
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "EP5_ACT3_STAGE4_END@197#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 197
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 185
L47_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L47_1.m_Pos = "R"
L48_1 = "글쎄? 사실은 나도 잘 몰라."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "さあね、私も実態はよくわかってないの。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Well, I'm not entirely sure."
L47_1.m_Talk_ENG = L48_1
L48_1 = "誰知道？其實我也不清楚。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "อืม ฉันก็ไม่แน่ใจทั้งหมดนะ"
L47_1.m_Talk_THA = L48_1
L48_1 = "Chà, tôi không chắc lắm."
L47_1.m_Talk_VTN = L48_1
L48_1 = "这个嘛，其实我也不清楚。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Da bin ich mir nicht sicher."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Eh bien, je suis pas vraiment sûre."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "EP5_ACT3_STAGE4_END@198#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 198
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 185
L48_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L48_1.m_Pos = "R"
L49_1 = "일반적인 리플레이서 인자와 프로그레시브 인자 중간 정도의 힘을 제공하고......"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "通常のリプレイサー・ファクターとプログレッシブ・ファクターの中間程度の力を与え……"
L48_1.m_Talk_JPN = L49_1
L49_1 = "All I know is that the magnitude of the power it awakens lies somewhere between normal Replacer Factors and Progressive Factors,"
L48_1.m_Talk_ENG = L49_1
L49_1 = "可替代因子提供了一般的克隆因子和可操控因子中等程度的力量……"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ฉันรู้แค่ว่าปริมาณพลังมหาศาลที่มันปลุกขึ้นมาได้นั้นอยู่ระหว่างรีเพลสเซอร์แฟกเตอร์ธรรมดากับโปรเกรสซีฟแฟกเตอร์"
L48_1.m_Talk_THA = L49_1
L49_1 = "Tất cả những gì tôi biết là cường độ sức mạnh mà nó đánh thức nằm ở đâu đó giữa Nhân Tố Nhân Bản bình thường và Nhân Tố Lũy Tiến,"
L48_1.m_Talk_VTN = L49_1
L49_1 = "可替代因子提供了一般的克隆因子和可操控因子中等程度的力量……"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Ich weiß nur, dass das Ausmaß der Kraft, die er erweckt, irgendwo zwischen den normalen Replacer-Faktoren und Progressiv-Faktoren liegt."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Ce que je sais, c'est que l'ampleur de la puissance qu'il éveille se situe quelque part entre l'agent substituteur et l'agent progressif,"
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "EP5_ACT3_STAGE4_END@199#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 199
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 185
L49_1.m_CutScenStrID = "EP5_ACT3_STAGE4_END"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L49_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L49_1.m_Pos = "R"
L50_1 = "약간의 부작용은 있지만 유지보수를 위한 추가적인 리플레이서 인자를 투여하지 않아도 붕괴하지 않는 안정적 변이인자라는 것 정도......"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "若干の副作用はあるけど、メンテナンスのためにリプレイサー・ファクターを追加で\n投与しなくても壊れることはない、安定的な変異因子だということくらいしか……"
L49_1.m_Talk_JPN = L50_1
L50_1 = "and that it's a stable type of Mutation Factor with minor side effects, which doesn't need additional Replacer Factor injections to stay active."
L49_1.m_Talk_ENG = L50_1
L50_1 = "雖然有一點副作用，但不需要服用維持用的追加克隆因子，身體也不會崩壞，是信賴度很高的變異因子……"
L49_1.m_Talk_TWN = L50_1
L50_1 = "และรู้ว่ามันเป็นมิวเทชั่นแฟกเตอร์ประเภทเสถียรที่มีผลข้างเคียงน้อย และไม่จำเป็นต้องมีการฉีดรีเพลสเซอร์แฟกเตอร์เพิ่มเติมเพื่อให้มีชีวิตต่อไป"
L49_1.m_Talk_THA = L50_1
L50_1 = "và đó là một loại Nhân Tố Đột Biến ổn định với các tác dụng phụ nhỏ, không cần tiêm thêm Nhân Tố Nhân Bản để duy trì hoạt động."
L49_1.m_Talk_VTN = L50_1
L50_1 = "有一点副作用，但是不用为了维持力量服用更多的克隆因子，是一种稳定性比较高的变异因子……"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Und dass es sich um eine stabile Form des Mutationsfaktors mit geringen Nebenwirkungen handelt. Es werden keine zusätzlichen Injektionen des Replacer-Faktors benötigt, um aktiv zu bleiben."
L49_1.m_Talk_DEU = L50_1
L50_1 = "et que c'est un agent de mutation stable, sans effets secondaires, qui n'a pas besoin d'injections supplémentaires d'agent substituteur pour rester actif."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
