L2_1 = "UNIT_PRIDE"
L1_1.m_Face = L2_1
L1_1.m_CharStrID = "SEOYOON_REPLACER_NULL_LANCE"
L1_1.m_Pos = "R"
L2_1 = "하지만 뭐가 됐든 상관없어."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "まあ、中身はどうだって良いの。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "What it is doesn't matter anymore."
L1_1.m_Talk_ENG = L2_1
L2_1 = "但不管那是什麼，我都不在乎。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "แต่นั่นก็ไม่สำคัญแล้วล่ะ"
L1_1.m_Talk_THA = L2_1
L2_1 = "Dù nó là gì không còn quan trọng nữa."
L1_1.m_Talk_VTN = L2_1
L2_1 = "但是是什么也无所谓了。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Aber wie auch immer, es spielt keine Rolle mehr."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Mais ça n'a plus d'importance."
