L4_1 = "그 여자의 최종 목적을 소각로에 처넣어서 불태워버릴 생각이니까."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "あの女の最終目的を焼却炉に放り込んで燃やしてしまうつもりだから。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "I'm going to shove the ultimate goal of the Replacers in the flames and burn it to ashes."
L3_1.m_Talk_ENG = L4_1
L4_1 = "那個女人的最終目的，要被我們扔到焚化爐裡燒掉。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ฉันจะโยนเป้าหมายสูงสุดของรีเพลสเซอร์เข้ากองไฟและเผาจนมันกลายเป็นขี้เถ้า"
L3_1.m_Talk_THA = L4_1
L4_1 = "Tôi sẽ đẩy mục tiêu cuối cùng của những Người Nhân Bản vào ngọn lửa và thiêu rụi nó thành tro bụi."
L3_1.m_Talk_VTN = L4_1
L4_1 = "让那个女人的最终目标灰飞烟灭。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Ich werde das Endziel der Replacer ins Feuer werfen und zu Asche verbrennen."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Je vais briser le but ultime des substituts et le réduire en miettes."
L3_1.m_Talk_FRA = L4_1
