L5_1 = "알겠지? 네가 바로 그 불을 지를 성냥이라고."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "わかった？　つまりあなたが、火をつけるためのマッチ役になるのよ。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Get it? And you're the match that's going to start the fire."
