L5_1 = "懂了嗎？妳就是那根點火的火柴。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "เข้าใจไหม? และเธอก็คือไม้ขีดที่ต้องใช้จุดไฟที่ว่า"
L4_1.m_Talk_THA = L5_1
L5_1 = "Hiểu chưa? Và bạn là que diêm sẽ bắt đầu bùng cháy."
L4_1.m_Talk_VTN = L5_1
L5_1 = "明白了吧？你就是能燃起那把火的火柴。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Verstehst du? Und du bist das Streichholz, das das Feuer entfachen wird."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Compris ? Et c'est toi qui vas lancer les hostilités."
L4_1.m_Talk_FRA = L5_1
